export const BESPOKE_SCHEMAS = {
  "aav-install-check": {"inputs":[{"key":"has_outdoor_vent","label":"At least one vent extends to the outdoors?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":null,"attrs":null},{"key":"ventilated_space","label":"Valve is in a ventilated space?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":null,"attrs":null},{"key":"accessible","label":"Valve remains accessible?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":null,"attrs":null}],"citation":"Citation: IPC 918 - individual and branch-type air admittance valves located not less than 4 in above the horizontal branch drain or fixture drain being vented (918.4); installed not less than 6 in above insulation materials (918.6); located in a ventilated space and remaining accessible; and, the requirement that governs everything else, at least one vent pipe extending to the OUTDOORS even where air admittance valves are used (918.7), because a valve admits air to relieve negative pressure and provides no relief of positive pressure. Valve capacity is rated in drainage fixture units per its ASSE 1051 or 1050 listing and is not interchangeable between individual, branch, and stack types. Not checked: whether AAVs are permitted at all by the adopted code and the AHJ, the developed length and sizing of the vent, the relief vent required where a horizontal branch is more than four branch intervals from the top of the stack, plenum restrictions, or the fixture arrangement below. A screen, not a code-official determination; the adopted code, the valve's listing, and the AHJ govern."},
  "accessible-toilet-compartment": {"inputs":[{"key":"wc_mounting","label":"Water closet mounting","kind":"select","options":[{"value":"wall-hung","label":"Wall hung (56 in deep min)"},{"value":"floor-mounted","label":"Floor mounted (59 in deep min)"}],"default":null,"attrs":null},{"key":"ambulatory_provided","label":"Ambulatory compartment provided?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":null,"attrs":null}],"citation":"Citation: 2010 ADA Standards for Accessible Design, 213.3.1 and 604.8. Section 213.3.1: where toilet compartments are provided, at least one shall comply with 604.8.1, and in addition at least one shall comply with 604.8.2 where six or more toilet compartments are provided or where the combination of urinals and water closets totals six or more fixtures. Section 604.8.1.1: wheelchair accessible compartments shall be 60 in wide minimum measured perpendicular to the side wall, and 56 in deep minimum for wall hung water closets and 59 in deep minimum for floor mounted water closets measured perpendicular to the rear wall. Section 604.8.2.1: ambulatory accessible compartments shall have a depth of 60 in minimum and a width of 35 in minimum and 37 in maximum. A US federal standard in the public domain. Not checked: door swing and the requirement that the door not swing into the minimum required area, toe clearance under the partitions and its exception at greater depths, grab bars, water closet centerline, clear floor and turning space in the room, lavatories and dispensers, the accessible route, children's-use dimensions, or the additional requirements of ANSI A117.1 and state and local accessibility law. A compartment sizing screen, not a restroom design; the 2010 ADA Standards and the AHJ govern."},
  "affinity-laws": {"inputs":[{"key":"target_kind","label":"Target","kind":"select","options":[{"value":"RPM","label":"RPM"},{"value":"CFM","label":"CFM"},{"value":"SP","label":"SP"},{"value":"kW","label":"kW"}],"default":null,"attrs":null}],"citation":"Citation: Fan affinity laws Q ~ N, P ~ N^2, kW ~ N^3. Public engineering."},
  "air-changes-hour": {"inputs":[{"key":"occupancy","label":"Occupancy (comparison band)","kind":"select","options":[{"value":"residential","label":"Residential (0.35-1)"},{"value":"office","label":"Office (4-10)"},{"value":"classroom","label":"Classroom (4-6)"},{"value":"lab","label":"Laboratory (6-12)"},{"value":"patient_room","label":"Patient room (6)"},{"value":"operating_room","label":"Operating room (20-25)"}],"default":null,"attrs":null}],"citation":"Citation: ACH = supply CFM x 60 / room volume (ft^3). Net delivered ACH uses the smaller of supply and return; their difference is the pressurization airflow. Target bands per ASHRAE 62.1-2022 (ventilation) and ASHRAE 170-2021 (healthcare). AHJ and the governing standard's full procedure govern. Free at ashrae.org for the TOCs."},
  "air-movers": {"inputs":[{"key":"water_class","label":"Water class","kind":"select","options":[{"value":"1","label":"Class 1"},{"value":"2","label":"Class 2"},{"value":"3","label":"Class 3"},{"value":"4","label":"Class 4"}],"default":null,"attrs":null}],"citation":"Citation: IICRC S500 consensus practice (referenced; not reproduced). Coverage in ft^2 per air mover varies by water class."},
  "antimicrobial-dilution": {"inputs":[{"key":"mode","label":"Dilution mode","kind":"select","options":[{"value":"oz_per_gal","label":"Ounces per gallon"},{"value":"ratio","label":"Ratio 1:N"}],"default":null,"attrs":null}],"citation":"Citation: The EPA-registered product label governs (FIFRA - the label is the law); dilution and coverage are read off the label, the defaults here are placeholders. IICRC S520-2024 by name: antimicrobials do not replace physical removal of growth. 128 fl oz per US gallon."},
  "arc-flash-screen": {"inputs":[{"key":"equipment_config","label":"Equipment configuration","kind":"select","options":[{"value":"open_air","label":"Open air"},{"value":"box","label":"Box / enclosed (Lee is conservative for box; IEEE 1584 needed)"}],"default":null,"attrs":null}],"citation":"Citation: Ralph Lee (1982) closed-form, public, pre-IEEE-1584. NFPA 70E-2024 §130.5 requires an arc-flash risk assessment by a qualified person before energized work. Free at nfpa.org/freeaccess for NFPA 70E TOC and Annex D."},
  "asme-shell-thickness": {"inputs":[{"key":"geometry","label":"Geometry","kind":"select","options":[{"value":"cylindrical","label":"Cylindrical shell"},{"value":"spherical","label":"Spherical shell"}],"default":null,"attrs":null}],"citation":"Citation: ASME BPVC Section VIII Division 1, UG-27 shell thickness under internal pressure, by section number. Cylindrical shell, circumferential stress on the longitudinal joint: t = P R / (S E - 0.6 P). Spherical shell: t = P R / (2 S E - 0.2 P). R is the INSIDE radius in the corroded condition, S the allowable stress at the design temperature, and E the joint efficiency; the corrosion allowance is added after the strength calculation. Validity: thickness not more than half the inside radius, and for the cylinder pressure not more than 0.385 S E - beyond either, the thick-wall rules of Appendix 1 govern. Both formulas and both limits were confirmed against two independent published sources. The longitudinal-stress case on the circumferential joint is a separate, rarely governing equation and is deliberately not included. No allowable-stress or joint-efficiency table is reproduced - both are entered. ASME BPVC Section VIII and the vessel engineer govern."},
  "backflow-sizing": {"inputs":[{"key":"hazard","label":"Hazard category (IPC 312)","kind":"select","options":[{"value":"high","label":"High / health hazard"},{"value":"low","label":"Low / non-health hazard"}],"default":null,"attrs":null},{"key":"assembly_type","label":"Intended assembly type","kind":"select","options":[{"value":"RP","label":"RP (reduced-pressure principle)"},{"value":"DC","label":"DC (double check)"},{"value":"PVB","label":"PVB (pressure vacuum breaker)"},{"value":"AVB","label":"AVB (atmospheric vacuum breaker)"}],"default":null,"attrs":null},{"key":"pipe_size_in","label":"Service / assembly size (in)","kind":"select","options":[{"value":"0.75","label":"3/4 in"},{"value":"1","label":"1 in"},{"value":"1.5","label":"1-1/2 in"},{"value":"2","label":"2 in"}],"default":null,"attrs":null}],"citation":"Citation: high (health) hazard requires a reduced-pressure principle (RP) assembly per IPC 312 / the cross-connection control program; downstream pressure = upstream - assembly head loss. Head loss interpolated from the bundled Watts technical-bulletin curves (representative; the assembly cut sheet and the USC FCCCHR approved-assembly list govern). Annual test required per EPA 40 CFR 141.85 / AWWA M14. AHJ governs. Free at codes.iccsafe.org and awwa.org for M14 TOC."},
  "ballnose-scallop-height": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"scallop-from-stepover","label":"Scallop from stepover"},{"value":"stepover-from-scallop","label":"Stepover from scallop"}],"default":null,"attrs":null}],"citation":"Citation: ballnose scallop height h = R - sqrt(R^2 - (s/2)^2) and its inverse s = 2 sqrt(R^2 - (R - h)^2), with the small-scallop h ~ s^2/(8R) approximation, per the CAM / mold-machining references, by name. Theoretical flat-surface cusp, not Ra. A shop aid; the real finish depends on the tool and slope."},
  "beam-loading": {"inputs":[{"key":"load_type","label":"Load type","kind":"select","options":[{"value":"uniform","label":"Uniform"},{"value":"point_center","label":"Centered point"}],"default":null,"attrs":null}],"citation":"Citation: M = w*L^2/8 (uniform), M = P*L/4 (centered point); deflection 5wL^4/(384*E*I) and PL^3/(48*E*I)."},
  "bearing-l10-life": {"inputs":[{"key":"bearing_type","label":"Bearing type","kind":"select","options":[{"value":"ball","label":"Ball (p = 3)"},{"value":"roller","label":"Roller (p = 10/3)"}],"default":null,"attrs":null}],"citation":"Citation: ISO 281 / ABMA 9 & 11 basic rating life: L10 = (C/P)^p x 10^6 rev, L10h = L10 / (60 x rpm), p = 3 ball / 10/3 roller. Life scales as the cube (ball) of the load ratio. Basic L10 assumes clean, well-lubricated operation; L10 is the life at which 10% have failed, not the average. A planning estimate; the mounting, lubrication, and application govern."},
  "bearing-max-load": {"inputs":[{"key":"bearing_type","label":"Bearing type","kind":"select","options":[{"value":"ball","label":"Ball (p = 3)"},{"value":"roller","label":"Roller (p = 10/3)"}],"default":null,"attrs":null}],"citation":"Citation: ISO 281 / ABMA 9 & 11 basic rating life solved for the load: P_max = C x (10^6 / L10_rev)^(1/p) with L10_rev = target_hr x 60 x rpm, p = 3 ball / 10/3 roller. Life scales as the cube (ball) of the load ratio. Basic L10 assumes clean, well-lubricated operation; L10 is the life at which 10% have failed, not the average. A planning estimate; the mounting, lubrication, and application govern."},
  "boiler-pipe-sizing": {"inputs":[{"key":"material","label":"Pipe material","kind":"select","options":[{"value":"copper","label":"Copper Type L (4 ft/s)"},{"value":"steel","label":"Steel Schedule 40 (6 ft/s)"},{"value":"pex","label":"PEX SDR-9 (3 ft/s)"}],"default":null,"attrs":null}],"citation":"Citation: GPM = Q / (500 x delta-T) (hydronic water energy balance); velocity = GPM / (2.448 x d^2); the smallest standard size at or below the velocity ceiling is recommended; head loss per Hazen-Williams (public domain, 1905). Per ASHRAE Systems and Equipment 2020 Ch. 13 (hydronic heating) with Bell & Gossett / Taco velocity limits. Free at ashrae.org for the TOC."},
  "bolt-proof-load": {"inputs":[{"key":"grade","label":"SAE grade","kind":"select","options":[{"value":"2","label":"Grade 2 (55 ksi proof)"},{"value":"5","label":"Grade 5 / A325 (85 ksi proof)"},{"value":"8","label":"Grade 8 / A490 (120 ksi proof)"}],"default":null,"attrs":null}],"citation":"Citation: SAE J429 inch-series bolt strength (ASME B1.1 tensile stress area): At = 0.7854 x (D - 0.9743/n)^2; proof / yield / tensile load = At x the grade strength (Grade 2: 55/57/74 ksi; Grade 5 / A325: 85/92/120; Grade 8 / A490: 120/130/150); recommended clamp = 75% of proof. The grade is read from the head markings. A design aid; the joint design and torque method govern."},
  "bonding-jumper": {"inputs":[{"key":"mode","label":"Jumper type","kind":"select","options":[{"value":"supply-side","label":"Supply-side (main / system)"},{"value":"equipment","label":"Equipment (load-side)"}],"default":null,"attrs":null},{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: NEC 250.28(D) / 250.102(C)(D) bonding-jumper sizing - supply-side from Table 250.66 (with the 12.5% rule above 1100 kcmil copper / 1750 aluminum), equipment from Table 250.122 (by section; only the threshold-to-size mapping is encoded). The AHJ-adopted edition governs. Free read-only at nfpa.org/freeaccess."},
  "breaker-sizing": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"single","label":"Single"},{"value":"three","label":"Three"}],"default":null,"attrs":null}],"citation":"Citation: per NEC 2023 §215.3, §230.79, §408.36. Continuous-load 125% rule per §210.20(A). Standard breaker sizes per §240.6. AHJ governs. Free at nfpa.org/freeaccess."},
  "brine-cure": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"brine","label":"Brine by volume"},{"value":"equilibrium","label":"Equilibrium cure by weight"}],"default":null,"attrs":null}],"citation":"Citation: First-principles mass-fraction chemistry. Prague Powder #1 is 6.25% sodium nitrite; finished-product ingoing nitrite is limited per USDA FSIS regulation (9 CFR 424.21/424.22, by name) - the user confirms the current FSIS limit. Free at fsis.usda.gov and ecfr.gov."},
  "cable-tray-fill": {"inputs":[{"key":"tray_type","label":"Tray type","kind":"select","options":[{"value":"ladder","label":"Ladder / ventilated trough"},{"value":"solid-bottom","label":"Solid bottom"}],"default":null,"attrs":null}],"citation":"Citation: Cable-tray fill per NEC Article 392.22 (the sum-of-diameters rule for cables 4/0 and larger and the cross-sectional-area allowance for smaller cables), by name. The AHJ-adopted NEC edition governs; ampacity derating for tray fill (392.80) is a separate check."},
  "carpet-restore-replace": {"inputs":[{"key":"water_category","label":"Water category","kind":"select","options":[{"value":"cat1","label":"Category 1 (clean)"},{"value":"cat2","label":"Category 2 (gray)"},{"value":"cat3","label":"Category 3 (black)"}],"default":null,"attrs":null},{"key":"component","label":"Component","kind":"select","options":[{"value":"carpet","label":"Carpet"},{"value":"cushion","label":"Cushion / pad"}],"default":null,"attrs":null}],"citation":"Citation: Carpet and cushion restore-vs-replace mapping (ANSI/IICRC S500), by name. The decision is a professional determination case by case (age, condition, contamination, customer agreement, and the AHJ all bear on it). Delaminated carpet is replaced; saturated cushion in any category is typically removed; Category 3 porous flooring is generally removed and disposed."},
  "category-deterioration": {"inputs":[{"key":"origin_category","label":"Origin category","kind":"select","options":[{"value":"cat1","label":"Category 1 (clean)"},{"value":"cat2","label":"Category 2 (gray)"},{"value":"cat3","label":"Category 3 (black)"}],"default":null,"attrs":null}],"citation":"Citation: Category-at-time-of-remediation principle (ANSI/IICRC S500), by name. Category is a professional determination made at the time of restoration, not by the source alone; elevated temperature and contact with contaminated materials accelerate the shift. The amplification window commonly cited is 48-72 hours under favorable conditions. When in doubt, the higher category is assumed."},
  "cattle-stocking-rate": {"inputs":[{"key":"animal_class","label":"Animal class","kind":"select","options":[{"value":"cow_calf","label":"Cow-calf pair (1.0 AU)"},{"value":"yearling","label":"Yearling (0.7 AU)"},{"value":"sheep","label":"Sheep (0.2 AU)"},{"value":"horse","label":"Horse (1.25 AU)"}],"default":null,"attrs":null}],"citation":"Citation: Per USDA NRCS National Range and Pasture Handbook Ch. 6 (stocking rate). available forage = production x area x utilization; AUMs = available / 780 lb (26 lb dry matter/day x 30 days per animal unit). Drought and climate adjustments are essential. Free at nrcs.usda.gov for the handbook."},
  "cctv-retention-days": {"inputs":[{"key":"recording_mode","label":"Recording mode","kind":"select","options":[{"value":"continuous","label":"Continuous 24 h"},{"value":"motion","label":"Motion duty-cycle"}],"default":null,"attrs":null}],"citation":"Citation: IP-video retention from available disk, camera count, bitrate, and recording hours (days = disk_GB / (cameras x bitrate x 0.45 x hours); 1 Mbps for 24 h is about 10.8 GB/day), per the standard NVR/VMS sizing practice (first-principles bitrate accounting); the H.264/H.265 bitrate estimates are scene- and vendor-specific and user-supplied. The VMS calculator and the installed cameras govern."},
  "cctv-storage": {"inputs":[{"key":"recording_mode","label":"Recording mode","kind":"select","options":[{"value":"continuous","label":"Continuous 24 h"},{"value":"motion","label":"Motion duty-cycle"}],"default":null,"attrs":null}],"citation":"Citation: IP-video storage and bandwidth from bitrate, recording hours, and retention (1 Mbps for 24 h is about 10.8 GB/day), per the standard NVR/VMS sizing practice (first-principles bitrate accounting); the H.264/H.265 bitrate estimates are scene- and vendor-specific and user-supplied. The VMS calculator and the installed cameras govern."},
  "ceiling-speaker-coverage": {"inputs":[{"key":"layout","label":"Layout","kind":"select","options":[{"value":"edge_to_edge","label":"Edge-to-edge (minimum count)"},{"value":"minimum_overlap","label":"Minimum overlap (even coverage)"}],"default":null,"attrs":null}],"citation":"Citation: Ceiling speaker coverage: diameter = 2 x (ceiling - ear) x tan(angle/2); spacing = diameter (edge-to-edge) or 0.7 x diameter (minimum overlap, -6 dB); count = ceil(area / spacing^2). A layout aid; verify with the speaker's coverage angle at the design frequency and the target SPL."},
  "center-of-gravity-2point": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"two-scale-weigh","label":"Two-scale weigh"},{"value":"pick-point-from-cg","label":"Reading from known CG"}],"default":null,"attrs":null}],"citation":"Citation: Center of gravity from a two-point weigh by moment balance (x = S2*L / (S1+S2)), per the standard rigging practice in the ASME B30.9 / ITI rigging references, by name; first-principles statics. A field aid - the lift plan, the rated rigging, and the qualified rigger / lift director govern."},
  "cfm-per-ton": {"inputs":[{"key":"climate","label":"Climate","kind":"select","options":[{"value":"standard","label":"Standard (400 CFM/ton)"},{"value":"humid","label":"Humid (350 CFM/ton)"},{"value":"dry","label":"Dry (450 CFM/ton)"}],"default":null,"attrs":null}],"citation":"Citation: Standard 400 CFM per ton with 350 for humid climates and 450 for dry climates."},
  "chiller-tons": {"inputs":[{"key":"fluid","label":"Fluid","kind":"select","options":[{"value":"water","label":"Water (500)"},{"value":"glycol_30","label":"30% propylene glycol"},{"value":"glycol_50","label":"50% propylene glycol"}],"default":null,"attrs":null}],"citation":"Citation: Q (BTU/hr) = GPM x factor x delta-T; tons = Q / 12000. The water factor 500 = 60 min/hr x 8.33 lb/gal x 1 BTU/lb-F (first-principles fluid energy balance). Glycol factors per ASHRAE Fundamentals 2021 Ch. 31 (secondary coolants). Free at ashrae.org for the TOC."},
  "chlorine-cylinder-withdrawal": {"inputs":[{"key":"container_type","label":"Container type","kind":"select","options":[{"value":"cylinder","label":"150-lb cylinder (~40 lb/day)"},{"value":"ton","label":"1-ton container (~400 lb/day)"}],"default":null,"attrs":null}],"citation":"Citation: gas chlorine container withdrawal rate (The Chlorine Institute; state operator training), by name. Per-container ceiling ~40 lb/day (150-lb cylinder) or ~400 lb/day (1-ton) at ~70 F, derated in a colder room; containers = ceil(feed / per-container). The withdrawal rate is a temperature-dependent latent-heat ceiling - pulling too fast frosts the container. Exceeding it forces a manifold or evaporator. The Chlorine Institute guidance and the manufacturer chart govern."},
  "coax-rg-loss": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"loss","label":"Loss over a run"},{"value":"max-run","label":"Max run for a target level"}],"default":null,"attrs":null}],"citation":"Citation: Coaxial-cable attenuation from the per-100-ft loss at frequency (loss = per-100-ft x length/100), per the cable manufacturer's published loss curves (Belden / CommScope) and the standard CATV/CCTV/SDI practice, by name; first-principles. The per-100-ft loss is type- and frequency-specific and user-supplied or a flagged default; the manufacturer's datasheet governs."},
  "codon-table": {"inputs":[{"key":"sequence_type","label":"Sequence type","kind":"select","options":[{"value":"rna","label":"RNA (ACGU)"},{"value":"dna","label":"DNA (ACGT, translated by T->U)"}],"default":null,"attrs":null}],"citation":"Citation: Standard genetic code (universal). Mitochondrial and a handful of bacterial / protozoan codes differ at specific codons and are NOT covered by this tile. The amino-acid three-letter / one-letter codes follow IUPAC-IUB nomenclature. Reading frame starts at position 1 of the entered sequence; this tile does not search for an internal AUG."},
  "combustion-lambda": {"inputs":[{"key":"fuel","label":"Fuel","kind":"select","options":[{"value":"natural_gas","label":"Natural gas (AFR 17.2)"},{"value":"propane","label":"Propane (AFR 15.5)"},{"value":"oil2","label":"#2 fuel oil (AFR 14.5)"}],"default":null,"attrs":null}],"citation":"Notice: A tuning aid, not a certified combustion test; the analyzer, the appliance, and the manufacturer instructions govern. Citation: combustion-analysis practice lambda and air-fuel ratio, by name. lambda = 20.9 / (20.9 - O2); excess_air = (lambda - 1) x 100; AFR_actual = lambda x AFR_stoich (17.2 natural gas, 15.5 propane, 14.5 #2 oil, by mass). Lambda is the same physics as excess air (lambda = 1 + excess_air/100), shown the way the instrument displays it. The oxygen form assumes complete combustion; sample dry, air-free oxygen in the flue."},
  "compressor-short-cycle": {"inputs":[{"key":"system_type","label":"System type","kind":"select","options":[{"value":"single","label":"Single-stage"},{"value":"two_stage","label":"Two-stage"},{"value":"inverter","label":"VRF / inverter"}],"default":null,"attrs":null}],"citation":"Citation: cycle rate N = N_max x 4 x X x (1 - X) where X is the runtime (load) fraction (the ASHRAE/AHRI part-load cycling model, peaking at 50% load); on-time = X x 60 / N. Minimum runtime and pressure-equalization delays per the Copeland Application Engineering Bulletin 17-1226 and ASHRAE Fundamentals 2021. Per-manufacturer guidance governs inverter systems. Free at copeland.com/literature."},
  "concrete": {"inputs":[{"key":"shape","label":"Shape","kind":"select","options":[{"value":"slab","label":"Slab"},{"value":"footing","label":"Footing"},{"value":"column","label":"Column"},{"value":"footing_with_stem","label":"Footing with stem"}],"default":null,"attrs":null}],"citation":"Citation: Geometric volume divided by 27 (cubic feet per cubic yard)."},
  "conductor-short-circuit-withstand": {"inputs":[{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper (K=0.0297, B=234)"},{"value":"aluminum","label":"Aluminum (K=0.0125, B=228)"}],"default":null,"attrs":null}],"citation":"Citation: ICEA P-32-382 / Onderdonk adiabatic short-circuit withstand (public-domain): (I/A)^2 t = K log10((T2+B)/(T1+B)); copper K=0.0297/B=234, aluminum K=0.0125/B=228. A thermal-withstand screen, not a substitute for the device time-current curve or an engineered study."},
  "conduit-fill": {"inputs":[{"key":"conduit","label":"Conduit type","kind":"select","options":[{"value":"EMT","label":"EMT"},{"value":"PVC_40","label":"PVC Schedule 40"},{"value":"RMC","label":"RMC"}],"default":null,"attrs":null}],"citation":"Citation: per NEC 2023 Chapter 9, Table 4 (conduit areas) and Chapter 9, Table 5 (conductor areas). Fill thresholds 53% (1 conductor), 31% (2 conductors), 40% (>= 3 conductors). AHJ governs. Free at nfpa.org/freeaccess."},
  "conduit-saddle": {"inputs":[{"key":"mode","label":"Saddle type","kind":"select","options":[{"value":"three-point","label":"Three-point"},{"value":"four-point","label":"Four-point"}],"default":null,"attrs":null},{"key":"preset","label":"Bend preset (center/outer)","kind":"select","options":[{"value":"45/22.5","label":"45/22.5 deg"},{"value":"60/30","label":"60/30 deg"}],"default":null,"attrs":null}],"citation":"Citation: Conduit saddle bending follows the field multipliers and shrink rules taught in the electrical apprenticeship and documented in Ugly's Electrical References and NECA conduit-bending guidance by name. Bender deduct and shoe figures are tool-specific - confirm against your bender. See the cable-bend-radius tile for minimum conductor bend radius. The AHJ governs."},
  "confidence-interval": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"proportion","label":"Proportion (binomial)"},{"value":"mean","label":"Mean (z-interval)"}],"default":null,"attrs":null},{"key":"confidence_pct","label":"Confidence level","kind":"select","options":[{"value":"80","label":"80%"},{"value":"90","label":"90%"},{"value":"95","label":"95%"},{"value":"98","label":"98%"},{"value":"99","label":"99%"}],"default":null,"attrs":null}],"citation":"Citation: Wald confidence interval. For a proportion: phat +/- z * sqrt(phat * (1-phat) / n). For a mean: xbar +/- z * (sd / sqrt(n)). z critical values from the standard normal: 80% = 1.2816, 90% = 1.6449, 95% = 1.96, 98% = 2.3263, 99% = 2.5758. The Wald interval under-covers when n*phat < 10 (use Wilson or Clopper-Pearson) and is z-based for the mean (use a t-interval for small n with unknown sigma)."},
  "copper-resistance": {"inputs":[{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: R(T) = rho_0 * L / A * (1 + alpha * (T - 20)). Resistivity and temperature coefficient from NIST tables."},
  "crane-power-line-clearance": {"inputs":[{"key":"option","label":"Which option","kind":"select","options":[{"value":"default","label":"Default clearance (voltage not determined)"},{"value":"table-a","label":"Table A (voltage determined)"},{"value":"deenergized","label":"Deenergized and visibly grounded"}],"default":null,"attrs":null}],"citation":"Citation: OSHA 29 CFR 1926.1408, a US federal regulation in the public domain. For power lines up to 350 kV the employer must either confirm from the utility owner or operator that the line has been deenergized and visibly grounded at the worksite; or ensure that no part of the equipment, load line, or load - including rigging and lifting accessories - gets closer than 20 feet to the line while implementing the encroachment-prevention measures of paragraph (b); or determine the line's voltage and use the Table A minimum clearance distance while implementing those same measures. Table A: up to 50 kV, 10 ft; over 50 to 200 kV, 15 ft; over 200 to 350 kV, 20 ft; over 350 to 500 kV, 25 ft; over 500 to 750 kV, 35 ft; over 750 to 1,000 kV, 45 ft; over 1,000 kV, as established by the utility owner or operator or a registered professional engineer who is a qualified person with respect to electrical power transmission and distribution. Not checked: the encroachment-prevention measures themselves, the planning meeting and work-zone identification, assembly and disassembly near power lines, travel with no load, or the utility's voltage confirmation. A screen, not a lift plan; Subpart CC, the utility, and the qualified person govern."},
  "crown-pruning-dose": {"inputs":[{"key":"maturity_class","label":"Maturity class","kind":"select","options":[{"value":"young","label":"Young (~15% cap)"},{"value":"mature","label":"Mature (25% cap)"},{"value":"over-mature","label":"Over-mature (~10% cap)"},{"value":"stressed","label":"Stressed (0% cap)"}],"default":null,"attrs":null}],"citation":"Citation: ANSI A300 Part 1 live-crown removal limit (ISA Best Management Practices), by name. removal_pct = removed / live x 100, compared to the class cap: mature <= 25% in a single season, young ~15%, over-mature ~10%, stressed 0%. The 25% is the mature maximum, not a target; lion's-tailing violates A300 even under the percent cap. A planning aid; a qualified arborist governs."},
  "curve-deflection-stakeout": {"inputs":[{"key":"mode","label":"Definition mode","kind":"select","options":[{"value":"radius","label":"By radius (ft)"},{"value":"degree","label":"By degree of curve"}],"default":null,"attrs":null}],"citation":"Citation: deflection-angle curve stakeout - deflection from the back tangent delta = (l / 2R)(180/pi) deg, sub-chord c = 2R sin(l / 2R), arc definition D = 5729.58 / R. First-principles route surveying per FM 5-233 Construction Surveying and AASHTO A Policy on Geometric Design (the Green Book), by name. Simple circular curve, no spiral/superelevation transition. A computational aid; the design of record governs."},
  "curve-grade-scaler": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"flat","label":"Flat add (raw + k)"},{"value":"sqrt","label":"Square-root (10 x sqrt(raw))"},{"value":"linear","label":"Linear rescale to target mean"}],"default":null,"attrs":null}],"citation":"Citation: Standard psychometric score-scaling methods (public): flat add, square-root, and linear rescale-to-target-mean. Estimate only - the instructor's gradebook and academic-integrity policy govern final grades."},
  "cylinder-storage-separation": {"inputs":[{"key":"barrier_present","label":"Barrier between them?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":null,"attrs":null},{"key":"barrier_noncombustible","label":"Barrier is noncombustible?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":null,"attrs":null},{"key":"cylinders_upright","label":"Cylinders secured upright?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":null,"attrs":null},{"key":"valve_caps_secured","label":"Valve protection caps in place and secured?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":null,"attrs":null}],"citation":"Citation: OSHA 29 CFR 1926.350, a US federal regulation in the public domain. 'Oxygen cylinders in storage shall be separated from fuel-gas cylinders or combustible materials (especially oil or grease), a minimum distance of 20 feet (6.1 m) or by a noncombustible barrier at least 5 feet (1.5 m) high having a fire-resistance rating of at least one-half hour.' 'Compressed gas cylinders shall be secured in an upright position at all times except, if necessary, for short periods of time while cylinders are actually being hoisted or carried.' 'Valve protection caps shall be in place and secured.' Not checked: cylinders in use rather than in storage; acetylene-specific storage and the waiting period after a cylinder has been on its side; regulator, hose, and torch condition; flashback arrestors; prohibited hoisting methods; transport in enclosed vehicles; indoor storage quantity limits; or NFPA 55 and state rules, which are often stricter. A screen, not a gas-storage plan; 1926.350, the gas supplier, and the AHJ govern."},
  "debt-yield": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"yield","label":"Debt yield (from a loan amount)"},{"value":"maxloan","label":"Max loan (from a target debt yield)"}],"default":null,"attrs":null}],"citation":"Citation: Debt yield = NOI / loan amount, a lender's return if it took the property back on day one. It ignores the interest rate, amortization, and cap rate, which is why it became the binding loan-sizing constraint in tight credit; typical minimums run 8-10%. The lender governs the required floor."},
  "decibel-converter": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"power-ratio","label":"Power ratio (10 log)"},{"value":"voltage-ratio","label":"Voltage/pressure ratio (20 log)"},{"value":"reference-level","label":"Reference level (back-solve linear)"},{"value":"combine","label":"Combine incoherent sources"}],"default":null,"attrs":null},{"key":"ref_type","label":"Reference type","kind":"select","options":[{"value":"dBu","label":"dBu (0.775 V)"},{"value":"dBV","label":"dBV (1 V)"},{"value":"dBSPL","label":"dBSPL (20 uPa)"}],"default":null,"attrs":null}],"citation":"Citation: Per ANSI S1.1 acoustical-terminology decibel definitions (power 10log, field-quantity 20log) and the standard reference levels (dBu 0.775 V, dBV 1 V, dBSPL 20 uPa), by name; public. Complements spl-distance."},
  "degree-day-energy": {"inputs":[{"key":"fuel","label":"Fuel","kind":"select","options":[{"value":"gas","label":"Gas (therms)"},{"value":"oil","label":"Fuel oil (gal)"},{"value":"electric","label":"Electric (kWh)"}],"default":null,"attrs":null}],"citation":"Citation: degree-day annual heating energy Q = 24 x HDD x UA (base-65 degF), fuel = Q/efficiency, with 1 therm = 100,000 Btu / 1 gal oil ~ 138,500 Btu / 1 kWh = 3,412 Btu, ASHRAE degree-day / RESNET basis, by name. Steady-state, no gains, heating only. An estimate, not a calibrated model."},
  "dehumidifier": {"inputs":[{"key":"water_class","label":"Water class","kind":"select","options":[{"value":"1","label":"Class 1"},{"value":"2","label":"Class 2"},{"value":"3","label":"Class 3"},{"value":"4","label":"Class 4"}],"default":null,"attrs":null}],"citation":"Citation: AHAM rating method (80 F / 60 percent RH) and an engineering field method scaled by job conditions. References IICRC S500."},
  "delta-wye-line-phase": {"inputs":[{"key":"configuration","label":"Connection","kind":"select","options":[{"value":"wye","label":"Wye (star)"},{"value":"delta","label":"Delta"}],"default":null,"attrs":null}],"citation":"Citation: first-principles three-phase winding relations. Wye: V_line = root-3 x V_phase, I_line = I_phase. Delta: V_line = V_phase, I_line = root-3 x I_phase. S = root-3 x V_line x I_line. The equipment nameplate governs the connection."},
  "disinfectant-dwell": {"inputs":[{"key":"product_class","label":"Product class","kind":"select","options":[{"value":"quat","label":"Quaternary ammonium (quat)"},{"value":"ahp","label":"Accelerated hydrogen peroxide (AHP)"},{"value":"bleach","label":"Sodium hypochlorite (bleach solution)"},{"value":"phenolic","label":"Phenolic"},{"value":"botanical","label":"Botanical / thymol"}],"default":null,"attrs":null}],"citation":"Citation: Antimicrobial contact-time principle (ANSI/IICRC S500 and S520), by name. Antimicrobials are EPA-registered pesticides whose label is the legal authority (FIFRA); the ranges shown are guidance and the specific product label governs the exact dwell. The surface must stay visibly wet for the full contact time, and disinfection requires pre-cleaning because product cannot penetrate soil."},
  "drainage-invert": {"inputs":[{"key":"slope_units","label":"Slope units","kind":"select","options":[{"value":"in_per_ft","label":"in/ft"},{"value":"percent","label":"%"}],"default":null,"attrs":null}],"citation":"Citation: invert-out = invert-in - slope x run; cover = surface - (invert-out + OD). Slope minimums per IPC 2021 Section 704; minimum cover, frost depth, and live-load bury are set by the adopted code and the engineer/survey of record."},
  "economizer-enthalpy-changeover": {"inputs":[{"key":"mode","label":"Changeover type","kind":"select","options":[{"value":"differential_enthalpy","label":"Differential enthalpy (accounts for humidity)"},{"value":"fixed_drybulb","label":"Fixed dry-bulb setpoint"}],"default":null,"attrs":null}],"citation":"Citation: Economizer high-limit changeover (ASHRAE 90.1 6.5.1.1.3): differential-enthalpy enables free cooling when outdoor enthalpy < return enthalpy (accounts for latent load); fixed-dry-bulb enables below a dry-bulb setpoint. A control aid; the 90.1 high-limit for the climate zone and the equipment sequence govern."},
  "edm-slope-reduction": {"inputs":[{"key":"angle_mode","label":"Angle type","kind":"select","options":[{"value":"zenith","label":"Zenith angle (from vertical, 90 = level)"},{"value":"vertical","label":"Vertical angle (from horizontal, 0 = level)"}],"default":null,"attrs":null}],"citation":"Citation: EDM / total-station slope reduction by right-triangle trigonometry - horizontal H = S sin(Z) = S cos(a), vertical V = S cos(Z) = S sin(a), where Z is the zenith angle (from vertical) and a the vertical angle (from horizontal); ground-to-ground elevation difference = V + instrument height - reflector height. Standard plane-survey reduction per Ghilani, Elementary Surveying, by name. No curvature/refraction or grid scale factor. A computational aid; the project control governs."},
  "egc-parallel-raceways": {"inputs":[{"key":"material","label":"Conductor material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: NEC 250.122(F), equipment grounding conductors for conductors in parallel, by section number. Where circuit conductors are paralleled in separate raceways, a full-size EGC sized from Table 250.122 to the rating of the circuit's overcurrent device is required in EACH raceway - the EGC is not divided among the parallel sets. The table lookup is delegated to this catalog's existing egc-sizing model rather than duplicated. EDITION NOTE: this is the 2023-and-earlier rule; the 2026 NEC revises 250.122(F) so the EGC in each raceway need not exceed the largest ungrounded conductor in that raceway. 250.122(B) proportional upsizing and the 250.122(A) never-larger-than-the-circuit-conductors limit still apply. The NEC as adopted and the AHJ govern."},
  "egc-sizing": {"inputs":[{"key":"material","label":"EGC material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: per NEC 2023 Table 250.122 (EGC size by upstream OCPD). AHJ governs. Free at nfpa.org/freeaccess."},
  "elevation-pressure-loss": {"inputs":[{"key":"mode","label":"Input mode","kind":"select","options":[{"value":"floors","label":"Number of floors"},{"value":"feet","label":"Elevation change (ft)"}],"default":null,"attrs":null},{"key":"direction","label":"Direction","kind":"select","options":[{"value":"up","label":"Up (loss)"},{"value":"down","label":"Down (gain)"}],"default":null,"attrs":null}],"citation":"Citation: Hydrostatic head 0.434 psi/ft (public). Fire-ground '5 psi per floor' standpipe approximation per IFSTA Pumping Apparatus Driver/Operator and the NFPA 14 design basis, by name. Feeds the pump discharge pressure tiles; distinct from pdp / standpipe-pdp which bundle friction and nozzle pressure."},
  "equal-spacing": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"max-gap","label":"Count from a maximum gap"},{"value":"count","label":"Gap from a desired count"}],"default":null,"attrs":null}],"citation":"Citation: Equal-spacing layout - N items of width w in a run R have N+1 equal gaps of (R - N x w)/(N+1) and a center-to-center pitch of gap + w; in max-gap mode the smallest N whose gap stays at or below the limit is ceil((R - gmax)/(w + gmax)) - first-principles arithmetic, public domain. The gap limit (for example the IRC R312.1.3 4-inch-sphere guard rule) is user-supplied; the adopted code governs."},
  "extinguisher-coverage": {"inputs":[{"key":"hazard_class","label":"Hazard class","kind":"select","options":[{"value":"A","label":"Class A - ordinary combustibles (75 ft)"},{"value":"B","label":"Class B - flammable liquids (enter 30 or 50 ft)"},{"value":"K","label":"Class K - cooking media (30 ft)"}],"default":null,"attrs":null}],"citation":"Citation: NFPA 10 - a maximum travel distance to a Class A extinguisher of 75 ft at all hazard levels, a maximum travel distance of 30 ft for Class K, a Class B travel distance of 30 or 50 ft depending on the extinguisher's B rating and the hazard level (entered, not assumed), and the 6.1.3.3 ceiling of 11,250 sq ft of coverage per extinguisher. The square-grid relation area = 2 x travel^2 is geometry, not a code value, and it reproduces the 11,250 exactly at 75 ft. Travel distance is measured along the PATH OF TRAVEL, not in a straight line, so the grid figure is an open-floor best case. The extinguisher RATING is a separate determination from NFPA 10's maximum-area-per-unit-of-A table by hazard classification, which is not reproduced here. Class D travel distances are not shipped. Also not checked: mounting height, signage, obstruction, inspection intervals, or whether extinguishers are required at all. A planning aid, not a fire-protection design; NFPA 10 as adopted and the AHJ govern."},
  "fan-motor-max-airflow": {"inputs":[{"key":"power_basis","label":"Power basis","kind":"select","options":[{"value":"motor","label":"Motor (nameplate) HP"},{"value":"brake","label":"Brake HP"}],"default":null,"attrs":null}],"citation":"Citation: AMCA / ASHRAE fan-power relation solved for airflow: CFM_max = 6356 x BHP x fan efficiency / TSP, from BHP = (CFM x SP) / (6356 x eta) (public). A motor (nameplate) HP converts to brake HP with the drive efficiency. Estimate; the fan curve and motor data govern. TSP must be total (external + internal)."},
  "fastener-pullout": {"inputs":[{"key":"fastener_type","label":"Fastener type","kind":"select","options":[{"value":"nail","label":"Nail"},{"value":"screw","label":"Screw"}],"default":null,"attrs":null}],"citation":"Citation: Withdrawal capacity W = G^2.5 * D * 1380 (lb per inch of penetration), where G is wood specific gravity and D is fastener shank diameter."},
  "feed-for-surface-finish": {"inputs":[{"key":"finish_basis","label":"Finish basis","kind":"select","options":[{"value":"ra","label":"Ra (arithmetic average)"},{"value":"rt","label":"Rt (peak-to-valley)"}],"default":null,"attrs":null}],"citation":"Citation: theoretical surface roughness solved for feed: f = sqrt(8 x nose_radius x Rt), from Rt = f^2 / (8 x r), Ra ~= Rt / 4 - first-principles scallop geometry as in Machinery's Handbook (Industrial Press), by name; public domain. The measured finish is rougher than this theoretical value, so leave margin."},
  "filter-pressure-drop": {"inputs":[{"key":"filter_type","label":"Filter class","kind":"select","options":[{"value":"merv8","label":"MERV 8"},{"value":"merv11","label":"MERV 11"},{"value":"merv13","label":"MERV 13"},{"value":"merv16","label":"MERV 16"},{"value":"hepa","label":"HEPA"}],"default":null,"attrs":null}],"citation":"Citation: face velocity = CFM / face area; pressure drop scales ~linearly with face velocity (Darcy regime), dp(V) = dp_ref x V / 300 fpm; fan power (kW) = (CFM x dp_in_wc / 6356) / fan efficiency x 0.7457. Clean / change-out drops are representative cut-sheet values; the MERV rating is per ASHRAE 52.2-2017 and the actual filter's cut sheet governs the drop. Free at ashrae.org for the ASHRAE 52.2 TOC."},
  "flange-bolt-torque": {"inputs":[{"key":"thread_series","label":"Thread series","kind":"select","options":[{"value":"UNC","label":"UNC (coarse)"},{"value":"8UN","label":"8UN (large flange)"}],"default":null,"attrs":null}],"citation":"Citation: Bolt-preload torque by the short-form T = K*D*F and the cross/star tightening sequence, per ASME PCC-1 Guidelines for Pressure Boundary Bolted Flange Joint Assembly and the ASME B16.5 flange classes, by name; the nut factor K, gasket seating stress, and target preload are joint- and lubricant-specific and user-supplied. A computational aid - the assembly procedure, gasket manufacturer, and the engineer of record govern the installed torque."},
  "flue-gas-combustion-eff": {"inputs":[{"key":"fuel","label":"Fuel","kind":"select","options":[{"value":"natural_gas","label":"Natural gas"},{"value":"propane","label":"Propane (LPG)"},{"value":"oil2","label":"#2 fuel oil"}],"default":null,"attrs":null}],"citation":"Notice: A tuning aid, not a certified combustion test or an AFUE rating; the analyzer, the appliance, and the manufacturer instructions govern. Citation: Siegert stack-loss method (DIN combustion-analysis practice as implemented by flue-gas analyzers), by name. CO2 = CO2max x (1 - O2 / 20.9); qA_pct = dT_C x (A1 / CO2 + B) with dT_C = (T_stack_F - T_air_F) x 5/9; eff_net = 100 - qA; eff_gross ~ eff_net x LHV/HHV. Constants (A1 / B / CO2max / LHV-HHV): natural gas 0.37 / 0.009 / 11.7% / 0.902, propane 0.475 / 0.000 / 13.7% / 0.920, #2 oil 0.50 / 0.007 / 15.4% / 0.939. The net figure is the European convention; US analyzers display the gross (HHV) basis, and the conversion here is approximate. Sample dry in the undiluted flue before the draft hood; a condensing appliance recovers latent heat this stack loss counts as lost."},
  "friction-loss": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"hazen-williams","label":"Hazen-Williams (water)"},{"value":"darcy-weisbach","label":"Darcy-Weisbach (water)"}],"default":null,"attrs":null}],"citation":"Citation: Hazen-Williams (1905, public domain). IPC 2021 referenced for application. Darcy-Weisbach with Colebrook-White for general fluid use. Free at codes.iccsafe.org."},
  "gas-appliance-connection": {"inputs":[{"key":"appliance","label":"Appliance","kind":"select","options":[{"value":"furnace","label":"Furnace"},{"value":"water-heater","label":"Water heater"},{"value":"boiler","label":"Boiler"},{"value":"range","label":"Range / cooking appliance"},{"value":"dryer","label":"Clothes dryer"},{"value":"illuminating","label":"Illuminating appliance"},{"value":"decorative-vented","label":"Decorative appliance in a vented fireplace"},{"value":"gas-fireplace","label":"Gas fireplace"},{"value":"outdoor-grill","label":"Outdoor grill"},{"value":"other","label":"Other"}],"default":null,"attrs":null},{"key":"shutoff_same_room","label":"Shutoff in the same room?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":null,"attrs":null},{"key":"shutoff_upstream","label":"Shutoff upstream of the connector?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":null,"attrs":null},{"key":"trap_present","label":"Sediment trap installed?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":null,"attrs":null},{"key":"trap_in_appliance","label":"Trap built into the appliance?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":null,"attrs":null}],"citation":"Citation: IFGC 409.5 - the appliance shutoff valve located in the same room as the appliance, within 6 ft of it, and installed upstream of the union, connector, or quick-disconnect device it serves, with shutoff valves serving movable appliances such as cooking appliances and clothes dryers considered accessible where installed behind them. IFGC 408.4 - where a sediment trap is not incorporated as part of the appliance, a sediment trap installed downstream of the appliance shutoff valve as close to the inlet of the appliance as practical, with illuminating appliances, ranges, clothes dryers, decorative vented appliances for installation in vented fireplaces, gas fireplaces, and outdoor grills excepted. IFGC 411.1.3.1 - connectors with an overall length not to exceed 3 ft, except range and domestic clothes dryer connectors at 6 ft. Not checked: connector listing and type, connectors passing through building elements, connector reuse, upstream piping size and pressure, clearances, venting, combustion air, CSST bonding, leak testing, or fuel and altitude approval. A screen; the adopted code, the appliance listing, and the AHJ govern."},
  "gas-appliance-demand": {"inputs":[{"key":"fuel","label":"Fuel","kind":"select","options":[{"value":"natural_gas","label":"Natural gas (~1,000 BTU/ft^3)"},{"value":"propane","label":"Propane (~2,516 BTU/ft^3)"}],"default":null,"attrs":null}],"citation":"Citation: IFGC 2021 Section 402 / NFPA 54 (National Fuel Gas Code) by name. cfh = total connected BTU/hr / heating value; default heating values (1,000 BTU/ft^3 natural gas, 2,516 BTU/ft^3 propane) are editable."},
  "gas-leak-hole-diameter": {"inputs":[{"key":"gas","label":"Gas","kind":"select","options":[{"value":"natural_gas","label":"Natural gas"},{"value":"propane","label":"Propane"}],"default":null,"attrs":null}],"citation":"Citation: d = sqrt( 4 Q / (3550 * c * pi * sqrt(dP / SG)) ), the orifice-flow leak approximation Q = 3550 c A sqrt(dP/SG) solved for the diameter. An estimate of the effective hole size, not a code leak-test method. Estimation only."},
  "gas-leak-rate": {"inputs":[{"key":"gas","label":"Gas","kind":"select","options":[{"value":"natural_gas","label":"Natural gas"},{"value":"propane","label":"Propane"}],"default":null,"attrs":null}],"citation":"Citation: Q = 3550 * c * A * sqrt(dP / SG). Orifice flow approximation for a small gas leak. Estimation only."},
  "gas-pipe-sizing": {"inputs":[{"key":"gas","label":"Gas","kind":"select","options":[{"value":"natural_gas","label":"Natural gas"},{"value":"propane","label":"Propane"}],"default":null,"attrs":null}],"citation":"Citation: per IFGC 2021 Table 402.4 (NFPA 54). Spitzglass low-pressure gas formula Q = 3550 * sqrt(d^5 * dP / (SG * L * (1 + 3.6/d + 0.03*d))), the diameter-correction term included as the tile computes it. AHJ governs. Free at codes.iccsafe.org."},
  "gear-mph-rpm": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"mph","label":"MPH"},{"value":"rpm","label":"RPM"}],"default":null,"attrs":null}],"citation":"Citation: Classical drivetrain kinematics; SAE J267 metric tire-size convention for decoding a tire code to diameter, by name. Pure geometry, public. Geometric (no-slip) speed - ignores tire and torque-converter slip. Consistent with the tire-gearing decoder."},
  "geothermal-loop": {"inputs":[{"key":"soil","label":"Soil class","kind":"select","options":[{"value":"sand","label":"Sand"},{"value":"clay","label":"Clay"},{"value":"rock","label":"Rock"}],"default":null,"attrs":null},{"key":"loop_type","label":"Loop type","kind":"select","options":[{"value":"vertical","label":"Vertical"},{"value":"horizontal","label":"Horizontal"}],"default":null,"attrs":null}],"citation":"Notice: Simplified estimate. A code-compliant ground-loop design requires a full IGSHPA procedure. Citation: BTU per linear foot benchmarks from public DOE technical reports."},
  "glycol-mix": {"inputs":[{"key":"glycol_type","label":"Glycol type","kind":"select","options":[{"value":"propylene","label":"Propylene (food/HVAC)"},{"value":"ethylene","label":"Ethylene (industrial)"}],"default":null,"attrs":null},{"key":"protection_mode","label":"Protection mode","kind":"select","options":[{"value":"freeze","label":"Freeze (full flow protection)"},{"value":"burst","label":"Burst (line-rupture only, less glycol)"}],"default":null,"attrs":null}],"citation":"Citation: Manufacturer freeze-point curves (Dow Dowfrost / Dowtherm). Attribution included with output."},
  "grille-face-velocity": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"size","label":"Required grille size (from a target velocity)"},{"value":"velocity","label":"Face velocity (from a gross grille size)"}],"default":null,"attrs":null}],"citation":"Citation: Grille/register sizing from the free area: face velocity V = cfm / (gross area x free-area ratio), or the required gross area = cfm / (target velocity x ratio). Supply grilles run about 400-700 fpm, returns slower (quieter), which is why a return is larger than a supply for the same airflow. The manufacturer's published free-area ratio and throw data govern the selection."},
  "groove-weld-length-for-load": {"inputs":[{"key":"weld_type","label":"Weld type","kind":"select","options":[{"value":"PJP","label":"PJP (partial penetration)"},{"value":"CJP","label":"CJP (complete penetration)"}],"default":null,"attrs":null},{"key":"electrode","label":"Electrode (FEXX)","kind":"select","options":[{"value":"E60","label":"E60"},{"value":"E70","label":"E70"},{"value":"E80","label":"E80"},{"value":"E90","label":"E90"},{"value":"E100","label":"E100"},{"value":"E110","label":"E110"}],"default":null,"attrs":null},{"key":"method","label":"Method","kind":"select","options":[{"value":"ASD","label":"ASD (allowable)"},{"value":"LRFD","label":"LRFD (design)"}],"default":null,"attrs":null}],"citation":"Citation: Groove weld (CJP / PJP) shear capacity (AISC 360 Table J2.5 weld-metal shear 0.60*FEXX on the effective throat; ASD 0.30*FEXX, LRFD 0.75*0.60*FEXX) solved for the length: L = load / (stress_ksi x 1000 x throat), per AWS D1.1 and AISC 360 §J2, by name. The WPS, inspector, and engineer of record govern."},
  "groove-weld-strength": {"inputs":[{"key":"weld_type","label":"Weld type","kind":"select","options":[{"value":"PJP","label":"PJP (partial penetration)"},{"value":"CJP","label":"CJP (complete penetration)"}],"default":null,"attrs":null},{"key":"electrode","label":"Electrode (FEXX)","kind":"select","options":[{"value":"E60","label":"E60"},{"value":"E70","label":"E70"},{"value":"E80","label":"E80"},{"value":"E90","label":"E90"},{"value":"E100","label":"E100"},{"value":"E110","label":"E110"}],"default":null,"attrs":null},{"key":"method","label":"Method","kind":"select","options":[{"value":"ASD","label":"ASD (allowable)"},{"value":"LRFD","label":"LRFD (design)"}],"default":null,"attrs":null}],"citation":"Citation: Groove weld (CJP / PJP) shear capacity - the AISC 360 Table J2.5 weld-metal shear strength 0.60*FEXX on the effective throat (ASD allowable 0.30*FEXX, LRFD design 0.75*0.60*FEXX) - per AWS D1.1 Structural Welding Code and AISC 360 §J2, by name; first-principles. A CJP weld with matching filler develops the base metal in tension/compression; the PJP effective throat is read off the qualified WPS. The WPS, inspector, and engineer of record govern. Complements the fillet-weld-strength tile."},
  "gross-rent-multiplier": {"inputs":[{"key":"rent_basis","label":"Rent basis","kind":"select","options":[{"value":"annual","label":"Annual"},{"value":"monthly","label":"Monthly"}],"default":null,"attrs":null}],"citation":"Citation: Standard income-approach screening metric (gross rent / gross income multiplier) per the Appraisal Institute's The Appraisal of Real Estate income approach, by name; USPAP governs the appraiser's value opinion. Distinct from cap-rate-dscr, which uses NOI, not gross rent. Screening only."},
  "grounding-electrode": {"inputs":[{"key":"electrode_type","label":"Electrode type","kind":"select","options":[{"value":"driven_rod","label":"Driven rod (Dwight 1936)"},{"value":"ring","label":"Buried ring (IEEE 142 §4.2.2)"},{"value":"plate","label":"Buried plate (IEEE 142 §4.2.3)"},{"value":"ufer","label":"Concrete-encased / Ufer (IEEE 142 §4.2.4)"}],"default":null,"attrs":null}],"citation":"Citation: Per IEEE 142-2007 (Green Book) §4. Dwight (1936) closed-form for driven rods. NEC 2023 §250.53 governs adoption. Soil resistivity varies seasonally; field megger reading is the authoritative value at the time of inspection. Free at standards.ieee.org for IEEE bibliographic data."},
  "grounding-electrode-conductor": {"inputs":[{"key":"material","label":"Service / GEC material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null},{"key":"electrode_type","label":"Electrode type","kind":"select","options":[{"value":"rod-pipe-plate","label":"Rod / pipe / plate"},{"value":"concrete-encased","label":"Concrete-encased (Ufer)"},{"value":"ground-ring","label":"Ground ring"},{"value":"water-pipe-or-steel","label":"Water pipe / building steel"}],"default":null,"attrs":null}],"citation":"Citation: NEC 250.66 grounding-electrode-conductor sizing with the 250.66(A)-(C) electrode caps (by section; only the threshold-to-size mapping is encoded, not a reproduced table). The AHJ-adopted edition governs. Free read-only at nfpa.org/freeaccess."},
  "growing-degree-days": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"standard","label":"Standard"},{"value":"modified","label":"Modified (cap/floor)"}],"default":null,"attrs":null}],"citation":"Citation: Per the USDA / NWS growing-degree-day method and McMaster & Wilhelm (1997), 'Growing degree-days: one equation, two interpretations,' Agric. & Forest Meteorology 87, by name. Corn 50/86 F base/cutoff is the land-grant extension convention. Free at university extension sites."},
  "hepa-filter-life": {"inputs":[{"key":"particulate_category","label":"Particulate category","kind":"select","options":[{"value":"low","label":"Low (light dust)"},{"value":"medium","label":"Medium (typical remediation)"},{"value":"high","label":"High (heavy demolition)"}],"default":null,"attrs":null}],"citation":"Citation: Estimated days = filter capacity (g) / (CFM * hours/day * loading rate). Loading rates from typical commercial HEPA pre-filter behavior."},
  "hiking-time": {"inputs":[{"key":"distance_unit","label":"Distance unit","kind":"select","options":[{"value":"mi","label":"Miles"},{"value":"km","label":"Kilometres"}],"default":null,"attrs":null},{"key":"ascent_unit","label":"Ascent unit","kind":"select","options":[{"value":"ft","label":"Feet"},{"value":"m","label":"Metres"}],"default":null,"attrs":null}],"citation":"Citation: Naismith's rule (W. W. Naismith, 1892) for hill-walking time - horizontal distance / pace plus 1 hour per 600 m of ascent - by name; first-principles plus the canonical ascent rate, public domain. A planning estimate; the terrain / fatigue factor and the leader's judgment govern."},
  "hood-exhaust": {"inputs":[{"key":"hood_type","label":"Type I hood type (ignored for Type II)","kind":"select","options":[{"value":"wall-canopy","label":"Wall-canopy"},{"value":"single-island","label":"Single-island canopy"},{"value":"double-island","label":"Double-island canopy"},{"value":"backshelf","label":"Backshelf"},{"value":"proximity","label":"Proximity"},{"value":"pass-over","label":"Pass-over"}],"default":null,"attrs":null},{"key":"hood_class","label":"Hood class","kind":"select","options":[{"value":"I","label":"Type I (grease, hot)"},{"value":"II","label":"Type II (vapor only)"}],"default":null,"attrs":null},{"key":"duty","label":"Cooking-appliance duty","kind":"select","options":[{"value":"light","label":"Light (steam, oven)"},{"value":"medium","label":"Medium (range, fryer)"},{"value":"heavy","label":"Heavy (charbroiler, wok)"},{"value":"extra-heavy","label":"Extra-heavy (solid-fuel, mesquite)"}],"default":null,"attrs":null}],"citation":"Citation: Per IMC 2021 §507.13 (Type I grease hoods) and §507.20 (Type II vapor-only hoods). Duty multipliers (200 / 300 / 400 / 550 cfm/ft for wall-canopy) are formula coefficients per the published IMC. NFPA 96-2024 governs grease-handling exhaust system design. Makeup air per IMC 508. AHJ governs final equipment selection. Free at codes.iccsafe.org for IMC TOC and at nfpa.org/freeaccess for NFPA 96 TOC."},
  "horizontal-curve": {"inputs":[{"key":"mode","label":"Definition mode","kind":"select","options":[{"value":"radius","label":"By radius (ft)"},{"value":"degree","label":"By degree of curve"}],"default":null,"attrs":null}],"citation":"Citation: Circular-curve geometry per AASHTO A Policy on Geometric Design of Highways and Streets (the Green Book) and FM 5-233 Construction Surveying, using first-principles trigonometry with the arc definition D = 5729.58 / R. The design of record and engineer of record govern."},
  "horizontal-sightline-offset": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"M","label":"Sightline offset M (from sight distance)"},{"value":"maxS","label":"Max sight distance S (from cleared offset)"}],"default":null,"attrs":null}],"citation":"Citation: AASHTO horizontal sightline offset (middle ordinate) per A Policy on Geometric Design of Highways and Streets (the Green Book): M = R (1 - cos(28.65 S / R)) with R to the inside-lane centerline (the vehicle's path); the inverse S = (R/28.65) arccos(1 - M/R). Assumes a continuous obstruction along the curve. A design aid, not a substitute for a licensed civil engineer's design."},
  "hos-math": {"inputs":[{"key":"profile","label":"Profile","kind":"select","options":[{"value":"property_70_8","label":"Property 70/8"},{"value":"property_60_7","label":"Property 60/7"},{"value":"passenger_70_7","label":"Passenger 60/7"}],"default":null,"attrs":null}],"citation":"Notice: Math aid for personal verification. The ELD on the truck is the legal record. Citation: per FMCSA 49 CFR 395 (Hours of Service). Free at ecfr.gov."},
  "hp-from-torque": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"hp","label":"Horsepower"},{"value":"torque","label":"Torque"},{"value":"rpm","label":"RPM"}],"default":null,"attrs":null}],"citation":"Citation: Classical definition of mechanical power (Watt's 33,000 ft-lb/min); SAE J1349 engine-power rating, by name. The constant 5252 is a pure derivation, fully public. Torque and HP are equal at 5252 RPM by definition."},
  "hx-lmtd-ntu": {"inputs":[{"key":"config","label":"Flow configuration","kind":"select","options":[{"value":"counterflow","label":"Counter-flow"},{"value":"parallel","label":"Parallel-flow"}],"default":null,"attrs":null}],"citation":"Citation: LMTD = (dT1 - dT2) / ln(dT1/dT2); Q = C x delta-T with C = GPM x fluid factor; UA = Q / LMTD; effectiveness = Q / (C_min x (Th_in - Tc_in)); NTU = UA / C_min. Per the TEMA standards and standard heat-transfer texts (Incropera, Cengel). Free at tema.org for the standards TOC."},
  "hydraulic-cylinder": {"inputs":[{"key":"direction","label":"Direction","kind":"select","options":[{"value":"extend","label":"Extend (full bore)"},{"value":"retract","label":"Retract (annulus)"}],"default":null,"attrs":null}],"citation":"Citation: First-principles fluid power per NFPA T2.13.7 cylinder definitions: F = P * A, with A the full bore on extension and the bore-minus-rod annulus on retraction; v = (GPM * 231) / (60 * A). AHJ and machine design govern. Free at nfpa.com for the NFPA fluid-power table of contents."},
  "hydrostatic-test": {"inputs":[{"key":"material","label":"System type","kind":"select","options":[{"value":"water","label":"Water (1.5x)"},{"value":"fuel_gas","label":"Fuel gas (1.25x)"}],"default":null,"attrs":null}],"citation":"Citation: Public engineering practice. Default multipliers 1.5 for water, 1.25 for fuel gas. Hold-time scales with system volume."},
  "inventory-turnover": {"inputs":[{"key":"industry_key","label":"Industry (for comparison)","kind":"select","options":[{"value":"","label":"(none)"}],"default":null,"attrs":null}],"citation":"Citation: turnover = COGS / avg inventory; DSI = period_days / turnover. Industry medians from U.S. Census ARTS / SBA, year stamped."},
  "lab-dilution": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"single","label":"Single (solve missing)"},{"value":"serial","label":"Serial"}],"default":null,"attrs":null}],"citation":"Citation: C1V1 = C2V2 dilution form. Serial mode applies the dilution factor at each step."},
  "langelier-index": {"inputs":[{"key":"temp_unit","label":"Temp unit","kind":"select","options":[{"value":"F","label":"Fahrenheit"},{"value":"C","label":"Celsius"}],"default":null,"attrs":null}],"citation":"Citation: Langelier (1936) saturation index as standardized in Standard Methods for the Examination of Water and Wastewater (APHA/AWWA/WEF) and AWWA practice, by name; method cited, not reproduced. The user supplies measured water-quality values. LSI predicts tendency, not rate."},
  "layout-squaring": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"find-diagonal","label":"Find diagonal"},{"value":"check-square","label":"Check square"}],"default":null,"attrs":null}],"citation":"Citation: The Pythagorean 3-4-5 right-angle layout method (public) and the standard foundation and deck squaring technique. A layout aid, not a substitute for a transit or string-line."},
  "lighting-beam": {"inputs":[{"key":"distance_unit","label":"Distance unit","kind":"select","options":[{"value":"ft","label":"Feet"},{"value":"m","label":"Metres"}],"default":null,"attrs":null},{"key":"source","label":"Intensity source","kind":"select","options":[{"value":"candela","label":"Center-beam intensity (candela)"},{"value":"lumens","label":"Total output (lumens) + beam angle"}],"default":null,"attrs":null}],"citation":"Citation: First-principles theatrical photometry - beam diameter = 2 x throw x tan(beam angle / 2); center illuminance by the inverse-square law E = candela / distance^2 (the form fixture photometric charts publish, e.g. ETC / manufacturer cut sheets), by name; public domain. The architectural lumen-method room average is a separate tile (lux-to-footcandle)."},
  "lighting-throw-for-pool": {"inputs":[{"key":"distance_unit","label":"Distance unit","kind":"select","options":[{"value":"ft","label":"Feet"},{"value":"m","label":"Metres"}],"default":null,"attrs":null}],"citation":"Citation: first-principles theatrical photometry solved for throw: throw = D / (2 x tan(beam angle / 2)), from beam diameter = 2 x throw x tan(beam angle / 2); public domain. The illuminance still falls with the square of the throw (check the lighting-beam tile). A wider beam reaches the same pool from a shorter throw."},
  "livestock-water-requirement": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"table","label":"Temperature table (interpolate)"},{"value":"intake","label":"Intake ratio (water per DMI)"}],"default":null,"attrs":null}],"citation":"Citation: Per NRC Nutrient Requirements of Beef Cattle / Dairy Cattle water-intake guidance and the USDA NRCS National Range and Pasture Handbook water section, by name; per-class gallon breakpoints user-supplied (table values, not reproduced). Distinct from thi-livestock. Free NRCS guidance at nrcs.usda.gov."},
  "log-limb-weight": {"inputs":[{"key":"species","label":"Species (green density)","kind":"select","options":[{"value":"red_oak","label":"Red oak (64)"},{"value":"white_oak","label":"White oak (62)"},{"value":"sugar_maple","label":"Sugar maple (58)"},{"value":"ash","label":"Ash (48)"},{"value":"elm","label":"Elm (54)"},{"value":"hickory","label":"Hickory (63)"},{"value":"douglas_fir","label":"Douglas-fir (44)"},{"value":"southern_pine","label":"Southern pine (52)"},{"value":"eastern_white_pine","label":"Eastern white pine (36)"},{"value":"cottonwood","label":"Cottonwood (49)"},{"value":"generic_hardwood","label":"Generic hardwood (58)"},{"value":"generic_softwood","label":"Generic softwood (45)"}],"default":null,"attrs":null}],"citation":"Citation: USDA FPL Wood Handbook green density by species by name. Frustum volume = (pi/3) x length x (r1^2 + r1 r2 + r2^2); weight = volume x green density. Weigh or over-estimate when in doubt."},
  "lux-to-footcandle": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"convert","label":"Convert lux <-> footcandle"},{"value":"room","label":"Room average (lumen method)"}],"default":null,"attrs":null}],"citation":"Citation: Per the IES Lighting Handbook lumen method and the exact 1 footcandle = 10.764 lux conversion (1 ft^2 = 0.092903 m^2). The room method returns an AVERAGE maintained illuminance, not a point value. Pairs with the lighting-density tile. Public photometric relations."},
  "machining-time": {"inputs":[{"key":"feed_mode","label":"Feed entry","kind":"select","options":[{"value":"rpm-ipr","label":"Spindle speed (RPM) x feed/rev (IPR)"},{"value":"direct","label":"Feed rate directly (IPM)"}],"default":null,"attrs":null}],"citation":"Citation: Cutting time as cut distance / feed rate, with feed rate = RPM x IPR - first-principles arithmetic as in Machinery's Handbook (Industrial Press), by name; public domain. Include tool approach and overtravel in the cut length."},
  "manual-j-cooling": {"inputs":[{"key":"insulation_level","label":"Insulation level","kind":"select","options":[{"value":"poor","label":"Poor"},{"value":"average","label":"Average"},{"value":"good","label":"Good"}],"default":null,"attrs":null},{"key":"window_type","label":"Window type","kind":"select","options":[{"value":"single","label":"Single pane"},{"value":"double","label":"Double pane"},{"value":"triple","label":"Triple pane"}],"default":null,"attrs":null}],"citation":"Citation: Simplified screening estimate from envelope conductance, infiltration, internal gains, solar, and latent loads. Code-compliant load calc requires ACCA Manual J (8th ed.). Licensed HVAC designer and AHJ govern. Free at codes.iccsafe.org for IMC references."},
  "manual-j-heating": {"inputs":[{"key":"insulation_level","label":"Insulation level","kind":"select","options":[{"value":"poor","label":"Poor"},{"value":"average","label":"Average"},{"value":"good","label":"Good"}],"default":null,"attrs":null},{"key":"window_type","label":"Window type","kind":"select","options":[{"value":"single","label":"Single pane"},{"value":"double","label":"Double pane"},{"value":"triple","label":"Triple pane"}],"default":null,"attrs":null}],"citation":"Citation: Simplified screening estimate from envelope conductance and infiltration. Code-compliant load calc requires ACCA Manual J (8th ed.). Licensed HVAC designer and AHJ govern. Free at codes.iccsafe.org for IMC references."},
  "manure-application-rate": {"inputs":[{"key":"form","label":"Manure form","kind":"select","options":[{"value":"solid","label":"Solid (lb/ton -> ton/acre)"},{"value":"liquid","label":"Liquid (lb/1,000 gal -> 1,000 gal/acre)"}],"default":null,"attrs":null}],"citation":"Citation: Nutrient-based manure rate per USDA NRCS Code 590 (Nutrient Management) and land-grant manure-management guidance: available nutrient per unit = total nutrient x first-year availability; application rate = crop requirement / available per unit. Solid manure is ton/acre, liquid is 1,000 gal/acre. The rate is set by the most limiting of N or P2O5 under the farm's nutrient-management plan; a manure test and the plan govern."},
  "markup": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"markup_percent","label":"Markup percent"},{"value":"margin_percent","label":"Margin percent"},{"value":"selling_price","label":"Selling price"}],"default":null,"attrs":null}],"citation":"Citation: markup = profit / cost; margin = profit / selling price. Bidirectional."},
  "material-removal-rate": {"inputs":[{"key":"mode","label":"Operation","kind":"select","options":[{"value":"milling","label":"Milling (WOC, DOC, feed IPM)"},{"value":"turning","label":"Turning (SFM, DOC, feed IPR)"},{"value":"drilling","label":"Drilling (drill dia, feed IPM)"}],"default":null,"attrs":null}],"citation":"Citation: Material removal rate as the swept volume per unit time (milling WOC x DOC x feed; turning 12 x SFM x DOC x feed/rev; drilling (pi x D^2 / 4) x feed) - first-principles geometry as in Machinery's Handbook (Industrial Press), by name; public domain."},
  "metal-weight": {"inputs":[{"key":"shape","label":"Shape","kind":"select","options":[{"value":"plate","label":"Plate / sheet"},{"value":"round-bar","label":"Round bar"},{"value":"square-bar","label":"Square bar"},{"value":"hex-bar","label":"Hex bar"},{"value":"round-tube","label":"Round tube"},{"value":"rect-tube","label":"Rectangular tube"},{"value":"angle","label":"Angle"},{"value":"flat-bar","label":"Flat bar"}],"default":null,"attrs":null}],"citation":"Citation: First-principles weight = volume x density. Densities are published nominal values for common alloys (a small bundled public reference) or user-supplied. Mill certs and actual alloy temper govern."},
  "min-conductor-for-vd": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"single","label":"Single phase"},{"value":"three","label":"Three phase"}],"default":null,"attrs":null},{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: first-principles I x R voltage drop (K = copper 12.9 / aluminum 21.2 ohm-cmil/ft at 75 C) solved for the smallest standard conductor at or below the target percent; the NEC FPN 3%/5% figures are advisory. Verify ampacity (310.16) and 110.14(C) terminations separately. Free read-only at nfpa.org/freeaccess."},
  "mixed-water-temp": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"find-blend","label":"Find blended temperature"},{"value":"find-mix-ratio","label":"Find mix ratio for a target"},{"value":"find-hot-flow","label":"Find hot flow for a target"}],"default":null,"attrs":null}],"citation":"Citation: First-principles mixing energy balance for blending hot and cold potable water (T_blend = (Qh*Th + Qc*Tc)/(Qh+Qc)); the delivery-temperature limits follow the ASSE 1017 (master tempering) and ASSE 1016/1070 (point-of-use scald-guard) device standards and the IPC/UPC scald provisions, by name. The listed mixing valve and the AHJ govern the installed setpoint."},
  "motor-branch-protection": {"inputs":[{"key":"device_type","label":"Protective device type","kind":"select","options":[{"value":"inverse-time breaker","label":"Inverse-time breaker (250%)"},{"value":"dual-element/time-delay fuse","label":"Dual-element / time-delay fuse (175%)"},{"value":"nontime-delay fuse","label":"Nontime-delay fuse (300%)"},{"value":"instantaneous-trip breaker","label":"Instantaneous-trip breaker (800%)"}],"default":null,"attrs":null}],"citation":"Citation: NEC 2023 430.52 and Table 430.52 (branch-circuit short-circuit and ground-fault protection) with 430.110 (disconnect ampere rating). Sized on the table FLC (430.6(A)); overload is separate (430.32). The AHJ governs. Free at nfpa.org/freeaccess."},
  "multi-load-vd": {"inputs":[{"key":"material","label":"Conductor material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: Cumulative I*R drop accumulated per segment using single-phase round-trip resistance per the Voltage Drop helper. See docs/derivations.md."},
  "mwbc-voltage-drop": {"inputs":[{"key":"awg","label":"Conductor size (AWG)","kind":"select","options":[{"value":"14","label":"14 AWG"},{"value":"12","label":"12 AWG"},{"value":"10","label":"10 AWG"},{"value":"8","label":"8 AWG"},{"value":"6","label":"6 AWG"}],"default":null,"attrs":null},{"key":"material","label":"Conductor material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: circuit analysis of a 120/240 V three-wire multiwire branch circuit. The two hots are out of phase and share a neutral carrying the difference of the leg currents, so with equal conductors of one-way resistance R the drops are VD_A = R(2 I_A - I_B) and VD_B = R(2 I_B - I_A). Balanced loading collapses to R x I - half the drop of a two-wire circuit, because the neutral carries nothing - and heavy unbalance drives the lighter leg's drop negative, a real neutral shift that raises it above nominal. Conductor resistance is computed from the entered size, material, and temperature by this catalog's own resistance model, not a recalled table; DC resistance only, ignoring AC reactance and power factor. NEC 210.4(B) requires a common disconnect, and the neutral must be pigtailed so removing a device cannot open it. The NEC as adopted and the AHJ govern."},
  "nucleic-acid-a260": {"inputs":[{"key":"na_type","label":"Nucleic-acid type","kind":"select","options":[{"value":"dsDNA","label":"Double-stranded DNA (factor 50)"},{"value":"ssDNA","label":"Single-stranded DNA (factor 33)"},{"value":"oligo","label":"Oligo (factor 33)"},{"value":"RNA","label":"RNA (factor 40)"}],"default":null,"attrs":null}],"citation":"Citation: Standard spectrophotometric nucleic-acid quantitation (Beer-Lambert at 260 nm); concentration = A260 x factor x dilution, factor 50 (dsDNA) / 33 (ssDNA, oligo) / 40 (RNA) ug/mL per A260; purity = A260 / A280. The factor is an empirical mass coefficient, not molar, and differs by strandedness. A 260/280 below ~1.8 (DNA) or ~2.0 (RNA) flags protein/phenol carryover. Assumes a clean 1 cm path and a blanked instrument. The sample and instrument govern."},
  "overhead-recovery-rate": {"inputs":[{"key":"basis","label":"Recovery basis","kind":"select","options":[{"value":"per-hour","label":"Per billable hour ($/hr)"},{"value":"markup","label":"Markup on direct cost (%)"}],"default":null,"attrs":null}],"citation":"Citation: overhead recovery = annual overhead / billable hours ($/hr) or / annual direct cost (% markup), standard contractor cost-recovery. Every billed hour or direct dollar carries its share. The contractor's books and billable volume govern."},
  "paint-coverage": {"inputs":[{"key":"surface_porosity","label":"Surface porosity","kind":"select","options":[{"value":"smooth","label":"Smooth"},{"value":"textured","label":"Textured"},{"value":"rough","label":"Rough"}],"default":null,"attrs":null}],"citation":"Citation: gallons = area / (coverage * surface_factor). 350 ft^2/gal smooth, 250 textured, 175 rough."},
  "payroll-withholding": {"inputs":[{"key":"pay_frequency","label":"Pay frequency","kind":"select","options":[{"value":"weekly","label":"Weekly"},{"value":"biweekly","label":"Biweekly"},{"value":"semimonthly","label":"Semimonthly"},{"value":"monthly","label":"Monthly"}],"default":null,"attrs":null},{"key":"filing_status","label":"Filing status","kind":"select","options":[{"value":"single","label":"Single (illustrative)"}],"default":null,"attrs":null}],"citation":"Citation: IRS Publication 15-T percentage method (illustrative single-filer brackets bundled). FICA per FICA at 6.2% / 1.45% / 0.9% Additional."},
  "per-diem": {"inputs":[{"key":"type","label":"Type","kind":"select","options":[{"value":"lodging","label":"Lodging"},{"value":"m_and_ie","label":"M&IE"}],"default":null,"attrs":null}],"citation":"Citation: GSA-published per-diem rates (U.S. government publication)."},
  "pf-correction": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"single","label":"Single phase"},{"value":"three","label":"Three phase"}],"default":null,"attrs":null}],"citation":"Citation: kVAR = kW * (tan(acos(PF1)) - tan(acos(PF2))). Capacitance from Q = V^2 * 2*pi*f*C at 60 Hz."},
  "pipe-cold-spring": {"inputs":[{"key":"material","label":"Material (sets coefficient)","kind":"select","options":[{"value":"steel","label":"Carbon steel A53"},{"value":"copper","label":"Copper Type L"},{"value":"ductile_iron","label":"Ductile iron"},{"value":"aluminum","label":"Aluminum 6061"},{"value":"pvc","label":"PVC Sch 80"},{"value":"cpvc","label":"CPVC"},{"value":"pex","label":"PEX"}],"default":null,"attrs":null}],"citation":"Citation: Pipe cold spring (cut-short) - the run is cut short by a fraction of the computed free thermal growth dL = alpha * L * dT and sprung into place at the install temperature, lowering the hot anchor and nozzle reactions - per ASME B31.1 Power Piping §119 / B31.9 Building Services Piping, by name; first-principles linear expansion. Cold spring does not reduce the cyclic stress range (B31.1 §119.10); B31.1 credits two-thirds of the cold spring in the reaction. The piping engineer governs the flexibility analysis."},
  "pipe-fitting-takeout": {"inputs":[{"key":"reference","label":"Reference dimension","kind":"select","options":[{"value":"center-to-center","label":"Center-to-center"},{"value":"face-to-face","label":"Face-to-face"}],"default":null,"attrs":null}],"citation":"Citation: Fitting take-out / make-up cut-length layout as taught in NCCER Pipefitting and the standard fitter's references, by name; first-principles. Fitting take-out and thread make-up are product- and schedule-specific and user-supplied; confirm against your fittings and the spool drawing. Cross-links rolling-offset and conduit-offset."},
  "pipe-pressure-rating": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"allowable_pressure","label":"Allowable pressure from wall"},{"value":"required_wall","label":"Required wall from pressure"}],"default":null,"attrs":null}],"citation":"Citation: ASME B31.1 Power Piping internal-pressure design - allowable pressure P = 2 S E (t - A) / (D - 2 y (t - A)); minimum wall t = P D / (2 (S E + P y)) + A - by name (B31.3 Process Piping uses the same form with its own allowables). The allowable stress S, joint efficiency E, and y-coefficient are read from the applicable code edition's tables for the specific material and temperature. This is a design screen, not a stamped calculation; the engineer of record and the AHJ govern."},
  "pipe-support-spacing": {"inputs":[{"key":"material","label":"Pipe material","kind":"select","options":[{"value":"copper","label":"Copper tube"},{"value":"steel","label":"Steel"},{"value":"cpvc","label":"CPVC"},{"value":"pvc","label":"PVC"},{"value":"pex","label":"PEX"},{"value":"cast_iron","label":"Cast iron"}],"default":null,"attrs":null},{"key":"orientation","label":"Orientation","kind":"select","options":[{"value":"horizontal","label":"Horizontal"},{"value":"vertical","label":"Vertical"}],"default":null,"attrs":null}],"citation":"Citation: IPC 2021 Table 308.5 (hanger spacing) and MSS SP-58 by name; the spacing table ships as editable breakpoints by material and size. hangers = ceil(run / max_spacing) + 1."},
  "pipe-velocity": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"velocity-from-flow","label":"Velocity from flow"},{"value":"max-flow-for-velocity","label":"Max flow for a velocity"}],"default":null,"attrs":null},{"key":"material","label":"Material","kind":"select","options":[{"value":"copper","label":"Copper (Type L)"},{"value":"cpvc","label":"CPVC"},{"value":"pex","label":"PEX"},{"value":"steel","label":"Steel (Sch 40)"}],"default":null,"attrs":null},{"key":"service","label":"Water service","kind":"select","options":[{"value":"hot","label":"Hot (lower copper ceiling)"},{"value":"cold","label":"Cold"}],"default":null,"attrs":null}],"citation":"Citation: Pipe-flow velocity from continuity (v = 0.4085*gpm/d^2) and the copper erosion-corrosion velocity limits (about 5 ft/s hot, 8 ft/s cold) per the Copper Development Association / ASTM and ASPE plumbing-design guidance, by name; first-principles. Pairs with pipe-sizing and friction-loss. Actual inside diameter, not nominal, governs."},
  "poe-budget": {"inputs":[{"key":"poe_class","label":"PoE class","kind":"select","options":[{"value":"af","label":"802.3af Type 1 (15.4 W)"},{"value":"at","label":"802.3at Type 2 (30 W)"},{"value":"bt3","label":"802.3bt Type 3 (60 W)"},{"value":"bt4","label":"802.3bt Type 4 (90 W)"}],"default":null,"attrs":null},{"key":"category","label":"Cable category","kind":"select","options":[{"value":"Cat5e","label":"Cat5e"},{"value":"Cat6","label":"Cat6"},{"value":"Cat6A","label":"Cat6A"}],"default":null,"attrs":null}],"citation":"Citation: IEEE 802.3 PoE classes (cited by name only). Cable resistance from manufacturer category benchmarks; copper alpha 0.00393 per K applied for ambient correction."},
  "polygon-miter": {"inputs":[{"key":"size_mode","label":"Size given as","kind":"select","options":[{"value":"side","label":"Side length (each piece)"},{"value":"flats","label":"Across flats (face-to-face width)"},{"value":"corners","label":"Across corners (point-to-point)"}],"default":null,"attrs":null}],"citation":"Citation: Regular-polygon frame geometry - each joint is mitered at 180/N degrees off square, the interior angle is (N-2) x 180/N, and the side relates to the across-flats width by s = flats x tan(180/N) and the across-corners diameter by s = corners x sin(180/N) - first-principles trigonometry, public domain. Reproduces the known miters (square 45, hexagon 30, octagon 22.5). Cut a scrap test joint and allow for blade kerf."},
  "pool-chlorine-dose": {"inputs":[{"key":"product","label":"Product","kind":"select","options":[{"value":"cal-hypo-65","label":"Cal-hypo 65% (granular)"},{"value":"liquid-12.5","label":"Liquid chlorine 12.5%"},{"value":"dichlor-56","label":"Dichlor 56%"},{"value":"trichlor-90","label":"Trichlor 90%"},{"value":"custom","label":"Custom (enter %)"}],"default":null,"attrs":null}],"citation":"Citation: free-chlorine dose = ppm x (gallons/1,000,000) x 8.34 lb, divided by the product available-chlorine fraction; liquid ~10 lb/gal. Product strengths: liquid 12.5%, cal-hypo 65%, dichlor 56%, trichlor 90%. Dose to a target and retest; the product label governs."},
  "pool-turnover": {"inputs":[{"key":"chlorine_type","label":"Chlorine product","kind":"select","options":[{"value":"cal_hypo","label":"Cal-hypo (65%)"},{"value":"trichlor","label":"Trichlor (90%)"},{"value":"liquid_bleach","label":"Liquid bleach (12.5%)"}],"default":null,"attrs":null}],"citation":"Citation: required flow = pool volume / (turnover hours x 60); chlorine product = volume x ppm x 8.34 / 1,000,000 / available-chlorine fraction. Per the NSPF Certified Pool Operator Handbook (2022) and ANSI/APSP/ICC 11. NSPF governs operator certification; AHJ governs adopted code. Free at phta.org for the APSP-11 TOC."},
  "pool-volume": {"inputs":[{"key":"shape","label":"Pool shape","kind":"select","options":[{"value":"rectangle","label":"Rectangle (L x W)"},{"value":"round","label":"Round (diameter)"},{"value":"oval","label":"Oval (L x W)"}],"default":null,"attrs":null}],"citation":"Citation: pool water volume - gallons = surface area x average depth x 7.48052 gal/ft^3, average depth = (shallow + deep)/2. Rectangle area = L x W, round = pi (D/2)^2, oval = (pi/4) L x W. First-principles geometry with the standard 7.48052 gal/ft^3 conversion, per the NSPF CPO Handbook pool-volume method, by name. A field estimate; a metered fill or plan takeoff is more exact."},
  "power-distro": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"three","label":"3-phase"},{"value":"single","label":"1-phase"}],"default":null,"attrs":null}],"citation":"Citation: First-principles AC power (P = V*I*PF; 3-phase adds sqrt(3)). The NEC continuous-load 80% rule and temporary-power Articles 520/525, by name; a qualified electrician and the AHJ govern temporary power. Distinct from neutral-imbalance. Free read-only at nfpa.org/freeaccess."},
  "power-triangle": {"inputs":[{"key":"sign","label":"Reactive sign","kind":"select","options":[{"value":"lagging","label":"Lagging (inductive)"},{"value":"leading","label":"Leading (capacitive)"}],"default":null,"attrs":null}],"citation":"Citation: First-principles AC power triangle: kVA^2 = kW^2 + kVAR^2; PF = kW / kVA; theta = arccos(PF). IEEE 1459 defines apparent, real, and reactive power; this tile handles the sinusoidal case. Free at standards.ieee.org for the IEEE 1459 abstract."},
  "ppe": {"inputs":[{"key":"category","label":"Water category","kind":"select","options":[{"value":"1","label":"Category 1"},{"value":"2","label":"Category 2"},{"value":"3","label":"Category 3"}],"default":null,"attrs":null}],"citation":"Citation: Typical PPE selection per OSHA general duty considerations and IICRC S500 (referenced, not reproduced)."},
  "pressure-tank-drawdown": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"find-drawdown","label":"Find drawdown from a tank"},{"value":"size-the-tank","label":"Size the tank for a drawdown"}],"default":null,"attrs":null}],"citation":"Citation: Pressure-tank drawdown from Boyle's law on the diaphragm air charge (drawdown = V * (Ppre_abs/Pin_abs - Ppre_abs/Pout_abs)) the worst-case cycle rate (maximum cycling occurs when demand is half the pump output, giving a minimum period of 4 x drawdown / pump_gpm, i.e. 15 x pump_gpm / drawdown cycles per hour), and the anti-short-cycle minimum-runtime rule (about 1 min per run), per the published pump/tank engineering practice (Amtrol/WellMate and the WQA references), by name; first-principles gas law. The pump manufacturer's minimum runtime and the installed precharge govern."},
  "primer-tm": {"inputs":[{"key":"method","label":"Method","kind":"select","options":[{"value":"auto","label":"Auto (Wallace <=14 nt, else GC%)"},{"value":"wallace","label":"Wallace 2(A+T)+4(G+C)"},{"value":"gc","label":"Basic GC%"}],"default":null,"attrs":null}],"citation":"Citation: Per Wallace R.B. et al., Nucleic Acids Research 6 (1979), for the short-oligo rule and Marmur & Doty, J Mol Biol 5 (1962) / standard molecular-biology references for the GC% formula, by name. Complements the pcr-master-mix tile. Nearest-neighbor (SantaLucia) thermodynamics is the modern gold standard. Free abstracts at pubmed.ncbi.nlm.nih.gov."},
  "pulling-tension": {"inputs":[{"key":"lubricant","label":"Lubricant","kind":"select","options":[{"value":"dry","label":"Dry (mu 0.50)"},{"value":"wax","label":"Wax (mu 0.35)"},{"value":"polymer","label":"Polymer (mu 0.20)"}],"default":null,"attrs":null}],"citation":"Citation: Capstan equation T_out = T_in * exp(mu * theta) accumulated per bend; sidewall pressure approximated as T / R. See docs/derivations.md."},
  "punch-capacity": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"thickness","label":"Max thickness (given a hole diameter)"},{"value":"diameter","label":"Max round-hole diameter (given a thickness)"}],"default":null,"attrs":null}],"citation":"Citation: punching force solved for capacity: max thickness = F / (pi x D x shear), max diameter = F / (pi x T x shear), from F = perimeter x thickness x shear strength (F = capacity_tons x 2000 lb) - first-principles as in Machinery's Handbook (Industrial Press), by name; public domain. The shear strength (~0.8 x UTS for mild steel) is user-supplied; keep press margin."},
  "punch-force": {"inputs":[{"key":"shape","label":"Hole shape","kind":"select","options":[{"value":"round","label":"Round (enter diameter)"},{"value":"rectangular","label":"Rectangular (enter two sides)"},{"value":"perimeter","label":"Enter cut perimeter directly"}],"default":null,"attrs":null}],"citation":"Citation: Punching force as sheared area times shear strength - F = perimeter x thickness x shear strength - first-principles as in Machinery's Handbook (Industrial Press), by name; public domain. The shear strength (~0.8 x UTS for mild steel) is user-supplied."},
  "pv-interconnection-busbar": {"inputs":[{"key":"method","label":"Interconnection method","kind":"select","options":[{"value":"opposite_end_load_side","label":"Load-side breaker, opposite end from main (120% rule)"},{"value":"load_side_other","label":"Load-side, other position / line-tap (100% rule)"},{"value":"supply_side_tap","label":"Supply-side tap (NEC 705.11; not a busbar rule)"}],"default":null,"attrs":null}],"citation":"Citation: Per NEC 2023 Article 705 (Interconnected Electric Power Production Sources). 705.12(B)(3) governs load-side interconnection (the 120% busbar allowance for a breaker at the opposite end of the busbar from the main); 705.11 governs supply-side connections. 'Opposite end of busbar' is a code term of art the AHJ inspector verifies at the panel. AHJ governs. Free at nfpa.org/freeaccess for the NEC table of contents."},
  "radiant-floor-output": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"surface_to_q","label":"Output from a surface temperature"},{"value":"q_to_surface","label":"Surface temperature for a target output"}],"default":null,"attrs":null}],"citation":"Citation: Radiant floor heat output q = 2 x (T_surface - T_room)^1.1 Btu/hr-ft^2 (ASHRAE / radiant-panel practice), with the ~85 F mean-surface comfort limit (~39 Btu/hr-ft^2 in a 70 F room). A design aid; the panel manufacturer's ratings govern."},
  "rebar": {"inputs":[{"key":"bar_size","label":"Bar size","kind":"select","options":[{"value":"#3","label":"#3"},{"value":"#4","label":"#4"},{"value":"#5","label":"#5"},{"value":"#6","label":"#6"}],"default":null,"attrs":null}],"citation":"Citation: Rebar quantity from grid spacing minus edge clearances on both axes."},
  "reduced-voltage-starter": {"inputs":[{"key":"starter_type","label":"Starter type","kind":"select","options":[{"value":"autotransformer","label":"Autotransformer (line = tap^2)"},{"value":"wye-delta","label":"Wye-delta (fixed 1/3)"},{"value":"solid-state","label":"Solid-state / reactor (line = tap)"}],"default":null,"attrs":null}],"citation":"Citation: reduced-voltage-starter current and torque (NEMA ICS 2; torque ~ voltage^2): autotransformer motor = tap x LRA, line = tap^2 x LRA, torque = tap^2 x LRT; wye-delta = 0.333x on current and torque; solid-state/reactor = tap x LRA on both with tap^2 x LRT. An autotransformer's line current is the tap squared. A design aid; the motor speed-torque curve and the load govern."},
  "reducer-offset": {"inputs":[{"key":"type","label":"Reducer type","kind":"select","options":[{"value":"concentric","label":"Concentric (centerline)"},{"value":"eccentric-flat-bottom","label":"Eccentric flat-on-bottom (invert)"},{"value":"eccentric-flat-top","label":"Eccentric flat-on-top (crown)"}],"default":null,"attrs":null}],"citation":"Citation: Reducer centerline offset = (large OD - small OD) / 2, and which surface stays continuous by type - concentric holds the centerline, eccentric flat-on-bottom holds the invert, eccentric flat-on-top holds the crown - first-principles geometry, with the standard lay lengths per ASME B16.9 (bundled value entered by the user; a non-standard reducer overrides). Flat-on-bottom keeps a drain self-cleaning and flat-on-top keeps a pump suction free of air. The lay length is a fitting dimension, not a code minimum."},
  "refrigerant-charging": {"inputs":[{"key":"suction_unit","label":"Suction unit","kind":"select","options":[{"value":"psig","label":"psig (gauge)"},{"value":"psia","label":"psia (absolute)"}],"default":null,"attrs":null},{"key":"liquid_unit","label":"Liquid unit","kind":"select","options":[{"value":"psig","label":"psig (gauge)"},{"value":"psia","label":"psia (absolute)"}],"default":null,"attrs":null}],"citation":"Citation: Manufacturer-attributed P-T tables (data/hvac/refrigerant-pt-tables.json). psig is the gauge default; toggle to psia per input. Manufacturer typical 8-12 °F superheat / 8-15 °F subcool when no charging chart applies."},
  "rolled-blank": {"inputs":[{"key":"reference","label":"Diameter reference","kind":"select","options":[{"value":"od","label":"Outside diameter (OD)"},{"value":"id","label":"Inside diameter (ID)"}],"default":null,"attrs":null}],"citation":"Citation: Developed blank length to roll plate into a cylinder - L = pi x neutral-axis diameter, neutral axis at k x thickness from the inside (default k = 0.5 mid-thickness) - first-principles arc-length geometry as in Machinery's Handbook (Industrial Press), by name; public domain."},
  "roof-drain-sizing": {"inputs":[{"key":"drain_slope","label":"Horizontal storm-drain slope","kind":"select","options":[{"value":"1/8","label":"1/8 in per ft"},{"value":"1/4","label":"1/4 in per ft"},{"value":"1/2","label":"1/2 in per ft"}],"default":null,"attrs":null}],"citation":"Citation: IPC 2021 Section 1106 (Tables 1106.2 vertical conductors, 1106.3 horizontal storm drains, 1106.6 roof drains) by name; the capacity tables ship as editable conservative breakpoints, not a transcribed table. Storm flow gpm = area x rainfall x 0.0104."},
  "sample-size-for-margin": {"inputs":[{"key":"confidence_pct","label":"Confidence level","kind":"select","options":[{"value":"80","label":"80%"},{"value":"90","label":"90%"},{"value":"95","label":"95%"},{"value":"98","label":"98%"},{"value":"99","label":"99%"}],"default":null,"attrs":null}],"citation":"Citation: sample size for a target margin of error on a proportion, the inverse of the Wald interval MOE = z * sqrt(p * (1-p) / n). Solving for n gives n = z^2 * p * (1-p) / E^2, rounded up. p = 0.5 is the conservative planning value (it maximizes p(1-p), so it gives the largest n and covers any true proportion). z critical values from the standard normal: 80% = 1.2816, 90% = 1.6449, 95% = 1.96, 98% = 2.3263, 99% = 2.5758. For small p or small n a Wilson or Clopper-Pearson design is more exact; this is the standard planning figure."},
  "se-tax": {"inputs":[{"key":"filing_status","label":"Filing status","kind":"select","options":[{"value":"single","label":"Single"},{"value":"mfj","label":"Married filing jointly"},{"value":"mfs","label":"Married filing separately"},{"value":"hoh","label":"Head of household"}],"default":null,"attrs":null}],"citation":"Citation: Schedule SE (Form 1040). Social Security wage base from SSA annual announcement; Additional Medicare 0.9% threshold from IRC 3101(b)(2)."},
  "seer-eer": {"inputs":[{"key":"from","label":"From","kind":"select","options":[{"value":"EER","label":"EER"},{"value":"SEER","label":"SEER"},{"value":"SEER2","label":"SEER2"},{"value":"EER2","label":"EER2"}],"default":null,"attrs":null}],"citation":"Citation: SEER and EER are rated under different conditions. The 1.12 conversion factor is an engineering approximation; actual values depend on the rating method."},
  "service-conductor-sizing": {"inputs":[{"key":"material","label":"Conductor material","kind":"select","options":[{"value":"copper","label":"Copper"},{"value":"aluminum","label":"Aluminum"}],"default":null,"attrs":null}],"citation":"Citation: NEC 2023 310.12(A)/(B) dwelling service/feeder 83% allowance (A_req = 0.83 x service rating, conductor from the Table 310.16 75 degC column; Table 310.12 tabulates 100 A -> #4 Cu, 200 A -> 2/0 Cu), by name. Single-phase 120/240 V dwelling only; adjustments and the neutral are separate. The AHJ governs."},
  "shackle-eyebolt-wll": {"inputs":[{"key":"hardware","label":"Hardware","kind":"select","options":[{"value":"shackle","label":"Shackle (side load)"},{"value":"shoulder_eyebolt","label":"Shoulder eye bolt (angular pull)"}],"default":null,"attrs":null}],"citation":"Citation: ASME B30.26 (Rigging Hardware) and ASME B18.15 / manufacturer eye-bolt data by name; the angular derate curves ship as editable approximations. Estimate - the rating plate governs."},
  "shock-approach-boundary": {"inputs":[{"key":"nominal_v_ac","label":"Nominal voltage (phase-to-phase, AC)","kind":"select","options":[{"value":"<50 V","label":"<50 V"},{"value":"50-150 V","label":"50-150 V"},{"value":"151-750 V","label":"151-750 V (e.g. 480 V)"},{"value":"751-15,000 V","label":"751 V - 15 kV"}],"default":null,"attrs":null}],"citation":"Citation: NFPA 70E-2024 Table 130.4 (AC shock approach boundaries) - limited approach (movable vs fixed) and restricted approach by nominal voltage. Shock boundaries only; the arc-flash boundary is separate. The employer's electrical safety program and 70E govern. Free at nfpa.org/freeaccess."},
  "sine-bar": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"angle","label":"Angle from a gauge-block stack"},{"value":"stack","label":"Gauge-block stack for a target angle"}],"default":null,"attrs":null}],"citation":"Citation: Sine bar angle setup - a bar of length L on a gauge-block stack of height H tilts to angle theta where sin(theta) = H / L, so theta = arcsin(H/L) and H = L x sin(theta) - first-principles trigonometry (the standard sine-bar / sine-plate relation as in Machinery's Handbook, by name). The gauge-block grade and surface-plate flatness govern the achievable accuracy."},
  "slope-from-level": {"inputs":[{"key":"from","label":"From","kind":"select","options":[{"value":"degrees","label":"degrees"},{"value":"percent","label":"percent"},{"value":"in_per_ft","label":"in / ft"}],"default":null,"attrs":null}],"citation":"Citation: Bidirectional between degrees, percent, and inches per foot. Companion to utility 18."},
  "smoke-residue-method": {"inputs":[{"key":"residue_type","label":"Observed smoke residue","kind":"select","options":[{"value":"dry","label":"Dry (fast, hot fire)"},{"value":"wet","label":"Wet (slow, smoldering)"},{"value":"protein","label":"Protein (kitchen)"},{"value":"fueloil","label":"Fuel oil / puffback"},{"value":"synthetic","label":"Synthetic (plastics)"}],"default":null,"attrs":null}],"citation":"Citation: Smoke residue type to cleaning method mapping (ANSI/IICRC S700), by name. A test-clean of an inconspicuous area GOVERNS the final method; solvent selection and substrate compatibility are the cleaner's call. This screen narrows the method, it is not a procedure."},
  "solar-egc-690-45": {"inputs":[{"key":"vd_upsized","label":"Conductors upsized for voltage drop?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":null,"attrs":null}],"citation":"Citation: NEC 2023 690.45 equipment grounding conductors for PV systems with Table 250.122: the EGC is sized from the governing overcurrent rating (or, where there is no OCPD, from the PV short-circuit current), never smaller than 14 AWG, and 690.45 waives the 250.122(B) proportional upsize so enlarging the circuit conductors for voltage drop does not enlarge the EGC. The NEC and the AHJ govern."},
  "speaker-impedance": {"inputs":[{"key":"topology","label":"Wiring topology","kind":"select","options":[{"value":"parallel","label":"Parallel"},{"value":"series","label":"Series"},{"value":"series-parallel","label":"Series-parallel"}],"default":null,"attrs":null}],"citation":"Citation: Ohm's-law series/parallel impedance combination (public); the amplifier-minimum-load check follows the manufacturer's rated minimum (user-supplied). A nominal-impedance estimate, real loudspeaker impedance is frequency-dependent, the amp spec governs."},
  "spray-drift-buffer": {"inputs":[{"key":"droplet_class","label":"Droplet class","kind":"select","options":[{"value":"very_coarse","label":"Very Coarse (base 5 ft)"},{"value":"coarse","label":"Coarse (base 10 ft)"},{"value":"medium","label":"Medium (base 20 ft)"},{"value":"fine","label":"Fine (base 40 ft)"}],"default":null,"attrs":null}],"citation":"Citation: USDA / land-grant extension drift-management guidance and the EPA pesticide label / Worker Protection Standard (40 CFR 170), by name. The product label is the law (FIFRA); the label's mandatory buffer and wind limits govern. This is a relative planning aid, not the required buffer."},
  "square-footage": {"inputs":[{"key":"shape","label":"Shape","kind":"select","options":[{"value":"rectangle","label":"Rectangle"},{"value":"triangle","label":"Triangle"},{"value":"trapezoid","label":"Trapezoid"},{"value":"circle","label":"Circle"}],"default":null,"attrs":null}],"citation":"Citation: Geometric area formulas for rectangle, triangle, trapezoid, and circle."},
  "superelevation": {"inputs":[{"key":"mode","label":"Solve for","kind":"select","options":[{"value":"e","label":"Required superelevation e (from radius)"},{"value":"rmin","label":"Minimum radius R_min (from max bank)"}],"default":null,"attrs":null}],"citation":"Citation: AASHTO point-mass curve model e + f = V^2/(15 R) per A Policy on Geometric Design of Highways and Streets (the Green Book): required superelevation e = V^2/(15 R) - f, minimum radius R_min = V^2/(15(e_max + f)); the side-friction factor f is from the AASHTO design-speed table and decreases with speed. A design aid, not a substitute for a licensed civil engineer's geometric design."},
  "superheat-subcool": {"inputs":[{"key":"mode","label":"Mode","kind":"select","options":[{"value":"superheat","label":"Superheat"},{"value":"subcool","label":"Subcool"}],"default":null,"attrs":null}],"citation":"Citation: Superheat = line temperature minus saturated temperature at suction pressure. Subcool = saturated temperature at liquid pressure minus liquid line temperature."},
  "tank-mix": {"inputs":[{"key":"product_unit","label":"Product unit","kind":"select","options":[{"value":"fl_oz","label":"fluid ounces (liquid)"},{"value":"pt","label":"pints (liquid)"},{"value":"qt","label":"quarts (liquid)"},{"value":"gal","label":"gallons (liquid)"},{"value":"oz","label":"ounces (dry)"},{"value":"lb","label":"pounds (dry)"}],"default":null,"attrs":null}],"citation":"Citation: The EPA pesticide label is the law (FIFRA); follow its rate, carrier volume, REI, and PPE. Tank-mix math first-principles: acres/tank = tank gal / GPA; product/tank = acres/tank x rate. NRCS Agronomy Technical Note 5 for spray calibration. The separate nozzle-output (GPA) calibration is the Chemical Application Rate (GPA) tile. Free at epa.gov/pesticide-labels."},
  "tank-volume": {"inputs":[{"key":"orientation","label":"Tank orientation","kind":"select","options":[{"value":"horizontal","label":"Horizontal cylinder"},{"value":"vertical","label":"Vertical cylinder"}],"default":null,"attrs":null},{"key":"linear_unit","label":"Dimension unit","kind":"select","options":[{"value":"in","label":"Inches"},{"value":"ft","label":"Feet"}],"default":null,"attrs":null}],"citation":"Citation: First-principles tank gauging. Horizontal cylinder partial volume from the circular-segment area A = R^2*acos((R-h)/R) - (R-h)*sqrt(2Rh-h^2) times length; vertical cylinder V = pi*R^2*depth. Public-domain geometry; flat ends assumed (dished heads need a head-type correction). US gallons = in^3 / 231."},
  "tankless-gpm": {"inputs":[{"key":"solve_for","label":"Solve for","kind":"select","options":[{"value":"gpm","label":"GPM from kBTU + dT"},{"value":"kbtu","label":"kBTU from GPM + dT"},{"value":"dt","label":"dT from kBTU + GPM"}],"default":null,"attrs":null}],"citation":"Citation: GPM = kBTU * 1000 / (8.33 * 60 * dT). 1 lb water requires 1 BTU per F; 1 gal water = 8.33 lb. Inlet temperatures by climate zone (NOAA design data)."},
  "tap-drill-size": {"inputs":[{"key":"thread_standard","label":"Thread standard","kind":"select","options":[{"value":"inch","label":"Inch (enter TPI; diameter in inches)"},{"value":"metric","label":"Metric (enter pitch in mm; diameter in mm)"}],"default":null,"attrs":null}],"citation":"Citation: Tap drill for a target percent of full thread - % = 76.98 x (D_major - D_drill) x TPI for 60-degree threads, so D_drill = D_major - % / (76.98 x TPI) - first-principles thread geometry as in Machinery's Handbook (Industrial Press), by name; public domain. The named letter / number drill is a chart lookup; this reports the nearest 1/64 in fraction."},
  "taper-diameter": {"inputs":[{"key":"known_end","label":"Which end is known","kind":"select","options":[{"value":"large","label":"Large end"},{"value":"small","label":"Small end"}],"default":null,"attrs":null}],"citation":"Citation: Taper setup inverse - the missing end diameter = known -/+ (TPF/12) x L, and the compound angle per side = atan(TPF/24) - first-principles trigonometry as in Machinery's Handbook (Industrial Press), by name; public domain."},
  "thi-livestock": {"inputs":[{"key":"unit","label":"Unit","kind":"select","options":[{"value":"F","label":"Fahrenheit"},{"value":"C","label":"Celsius"}],"default":null,"attrs":null},{"key":"ventilation","label":"Ventilation","kind":"select","options":[{"value":"closed","label":"Closed / housed"},{"value":"open","label":"Open / pasture"}],"default":null,"attrs":null}],"citation":"Citation: Per USDA-ARS livestock heat-stress research publications and Kansas State University Cooperative Extension. Public domain. Free at usda.gov and at K-State Research and Extension."},
  "thread-measure-wire": {"inputs":[{"key":"thread_standard","label":"Thread standard","kind":"select","options":[{"value":"inch","label":"Inch (enter TPI)"},{"value":"metric","label":"Metric (enter pitch in mm)"}],"default":null,"attrs":null}],"citation":"Citation: The three-wire measurement-over-wires method for 60-degree threads - best wire W = 0.57735 x P, M = E + 3W - 0.86603 x P - first-principles geometry as in Machinery's Handbook (Industrial Press), by name; public domain. The pitch diameter E is user-supplied (no thread-class table lookup)."},
  "thread-pitch": {"inputs":[{"key":"thread_standard","label":"Thread standard","kind":"select","options":[{"value":"inch","label":"Inch (UN/UNC/UNF: enter TPI)"},{"value":"metric","label":"Metric (ISO: enter pitch in mm)"}],"default":null,"attrs":null}],"citation":"Citation: Thread pitch, lead, and 60-degree form - Unified (UN/UNC/UNF) inch and ISO metric threads share a 60-degree included angle; inch pitch P = 1 / TPI, metric pitch is the millimetre value (TPI = 25.4 / P), lead = pitch x starts, and the sharp-V fundamental height H = P x sqrt(3) / 2 - first-principles geometry as in Machinery's Handbook (Industrial Press), by name. The truncated thread depth and tap-drill size are thread-form- and class-specific and are not computed here."},
  "thread-pitch-dia-from-wires": {"inputs":[{"key":"thread_standard","label":"Thread standard","kind":"select","options":[{"value":"inch","label":"Inch (enter TPI)"},{"value":"metric","label":"Metric (enter pitch in mm)"}],"default":null,"attrs":null}],"citation":"Citation: The three-wire method for 60-degree threads solved for the pitch diameter - E = M - 3W + 0.86603 x P, best wire W = 0.57735 x P - first-principles geometry as in Machinery's Handbook (Industrial Press), by name; public domain. Compare E to the thread-class limits."},
  "transformer-sizing": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"three","label":"Three"},{"value":"single","label":"Single"}],"default":null,"attrs":null}],"citation":"Citation: Apparent power S = P / pf; three-phase FLA = (S * 1000) / (sqrt(3) * V_LL); single-phase FLA = (S * 1000) / V."},
  "trap-primer": {"inputs":[{"key":"zone","label":"Building zone","kind":"select","options":[{"value":"occupied","label":"Occupied space"},{"value":"mech_room","label":"Mechanical room"},{"value":"parking","label":"Parking structure"}],"default":null,"attrs":null},{"key":"prime_method","label":"Prime method","kind":"select","options":[{"value":"electronic","label":"Electronic (up to 4 drains)"},{"value":"pressure_drop","label":"Pressure-drop (up to 4 drains)"},{"value":"pump_discharge","label":"Pump-discharge (up to 4 drains)"},{"value":"manual","label":"Manual (1 drain)"}],"default":null,"attrs":null}],"citation":"Citation: primers = ceil(floor drains / drains-per-distribution-unit); annual water = drains x (oz per cycle / 128) x cycles per year. Per IPC 2021 §1002.4 (trap seals) with manufacturer flow rates from published cut sheets (Precision Plumbing Products / Sioux Chief / Mifab). AHJ governs. Free at codes.iccsafe.org."},
  "two-sample-t-test": {"inputs":[{"key":"tail","label":"Tail","kind":"select","options":[{"value":"two","label":"Two-sided"},{"value":"one","label":"One-sided"}],"default":null,"attrs":null}],"citation":"Citation: Per OpenIntro Statistics Chapter 7 (inference for numerical data, Welch's t) and the Welch-Satterthwaite df, by name; the t-CDF reuses the bundled special-function helper. Free at openintro.org."},
  "two-stroke-mix": {"inputs":[{"key":"fuel_unit","label":"Fuel unit","kind":"select","options":[{"value":"gallon","label":"US gallons"},{"value":"liter","label":"liters"}],"default":null,"attrs":null}],"citation":"Citation: Two-stroke fuel/oil mix - oil volume = fuel volume / ratio (gas:oil by volume); 1 US gallon = 128 fl oz, 1 fl oz = 29.5735 mL - first-principles volume arithmetic, public. Use the oil grade and ratio the equipment maker specifies; the equipment manual governs."},
  "two-stroke-mix-ratio-check": {"inputs":[{"key":"fuel_unit","label":"Fuel unit","kind":"select","options":[{"value":"gallon","label":"US gallons"},{"value":"liter","label":"liters"}],"default":null,"attrs":null}],"citation":"Citation: Two-stroke mix ratio check - ratio = fuel volume / oil volume (gas:oil by volume); 1 US gallon = 128 fl oz - first-principles volume arithmetic, the inverse of the two-stroke mix tile, public. Use the oil grade and ratio the equipment maker specifies; the equipment manual governs."},
  "utm-conversion": {"inputs":[{"key":"direction","label":"Direction","kind":"select","options":[{"value":"latlon_to_utm","label":"Lat/Lon -> UTM"},{"value":"utm_to_latlon","label":"UTM -> Lat/Lon"}],"default":null,"attrs":null},{"key":"hemisphere","label":"Hemisphere","kind":"select","options":[{"value":"N","label":"N"},{"value":"S","label":"S"}],"default":null,"attrs":null}],"citation":"Citation: Krueger / USGS public-domain UTM forward and inverse formulas. WGS84 datum."},
  "vbelt-drive": {"inputs":[{"key":"belt_section","label":"Belt cross-section","kind":"select","options":[{"value":"A","label":"A"},{"value":"B","label":"B"},{"value":"C","label":"C"},{"value":"D","label":"D"},{"value":"3V","label":"3V"},{"value":"5V","label":"5V"},{"value":"8V","label":"8V"}],"default":null,"attrs":null}],"citation":"Citation: ratio = driver_rpm / driven_rpm = D_driven / D_driver; belt length L = 2C + (pi/2)(D1+D2) + (D2-D1)^2/(4C) per ANSI/RMA IP-20 / IP-22. HP-per-belt is a coarse planning default by cross-section; the manufacturer's speed-specific power table (Gates Industrial Drive Design Manual) and service-factor table govern the final selection. Free at gates.com/literature."},
  "vent-terminal-check": {"inputs":[{"key":"roof_other_use","label":"Roof used for anything but weather protection?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes - 7 ft applies"}],"default":null,"attrs":null}],"citation":"Citation: IPC 903.1 - open vent pipes extending through a roof terminated not less than 6 in above the roof or 6 in above the anticipated snow accumulation, whichever is greater, except not less than 7 ft where the roof is used for any purpose other than weather protection. IPC 903.1.1 - where the 97.5-percent value for outdoor design temperature is 0 degF or less, vent extensions through a roof or wall not less than 3 in in diameter, with any increase in the size of the vent made not less than 1 ft inside the thermal envelope of the building. IPC 903.2 - an open vent terminal not located directly beneath any door, openable window, or other air intake of the building or of an adjacent building, and not within 10 ft horizontally of such an opening unless it is 3 ft above it. Anticipated snow accumulation and the design temperature are local figures. Not checked: the vent SIZE from drainage fixture units and developed length, whether a vent is required, the branch below, flashing, wall terminations, or fuel-gas venting. A screen, not a code-official determination; the adopted code and the AHJ govern."},
  "vessel-head-volume": {"inputs":[{"key":"head_type","label":"Head type","kind":"select","options":[{"value":"elliptical","label":"2:1 semi-elliptical"},{"value":"fd","label":"ASME flanged & dished (approx)"},{"value":"hemispherical","label":"Hemispherical"}],"default":null,"attrs":null}],"citation":"Citation: dished-head volume geometry by name. 2:1 semi-elliptical head = pi D^3/24; hemispherical = pi D^3/12; ASME flanged-and-dished (torispherical) ~ 0.0847 D^3 (standard crown/knuckle, approximate); straight flange = pi/4 D^2 x length. US gallons = in^3 / 231."},
  "voltage-drop-reactance": {"inputs":[{"key":"phase","label":"Phase","kind":"select","options":[{"value":"three","label":"Three-phase"},{"value":"single","label":"Single-phase"}],"default":null,"attrs":null}],"citation":"Citation: Vd = k * I * (R*cos(theta) + X*sin(theta)) * L / 1000, k = 2 single-phase / 1.732 three-phase. R and X per 1000 ft come from NEC 2023 Chapter 9 Table 9, selected by conductor size and conduit material (steel raceway raises X); enter them from your code book. NEC 210.19(A) Note 4 (3% branch) and 215.2(A)(1) Note 2 (5% total) set the advisory band. AHJ governs. Free at nfpa.org/freeaccess for the NEC table of contents."},
  "volumetric-efficiency": {"inputs":[{"key":"cycle","label":"Cycle","kind":"select","options":[{"value":"four","label":"4-stroke"},{"value":"two","label":"2-stroke"}],"default":null,"attrs":null}],"citation":"Citation: Classical four-stroke airflow derivation; SAE engine-test conventions, by name. The 3456/1728 constants are pure unit derivations, public (in every engine-builder reference). VE above 100% is legitimate for forced induction."},
  "water-heater-input": {"inputs":[{"key":"heater_type","label":"Heater type","kind":"select","options":[{"value":"gas_atmospheric","label":"Gas, atmospheric (0.80)"},{"value":"gas_condensing","label":"Gas, condensing (0.94)"},{"value":"electric","label":"Electric (0.98)"}],"default":null,"attrs":null}],"citation":"Citation: input = (recovery_gph x 8.33 x delta-T) / efficiency, from gph = (input BTU/hr x efficiency) / (8.33 x delta-T); electric kW = input / 3412. 8.33 BTU per gallon per degree F is first-principles water properties. Per DOE 10 CFR 430 and AHRI 1300. Free at energy.gov/eere and ahri.org."},
  "water-heater-recovery": {"inputs":[{"key":"heater_type","label":"Heater type","kind":"select","options":[{"value":"gas_atmospheric","label":"Gas, atmospheric (0.80)"},{"value":"gas_condensing","label":"Gas, condensing (0.94)"},{"value":"electric","label":"Electric (0.98)"}],"default":null,"attrs":null}],"citation":"Citation: gph = (input BTU/hr x efficiency) / (8.33 x delta-T). 8.33 BTU per gallon per degree F is first-principles water properties. Per DOE 10 CFR 430 and AHRI 1300. First-hour rating = recovery + 70% of stored volume (DOE FHR convention). Free at energy.gov/eere and ahri.org."},
  "water-service-pressure-check": {"inputs":[{"key":"has_check_or_backflow","label":"Check valve or backflow preventer on the service?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":null,"attrs":null},{"key":"has_storage_water_heater","label":"Storage water heater?","kind":"select","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"default":null,"attrs":null},{"key":"expansion_control_present","label":"Thermal expansion control installed?","kind":"select","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes"}],"default":null,"attrs":null}],"citation":"Citation: IPC 604.8 - static water pressure not greater than 80 psi, with an approved pressure-reducing valve conforming to ASSE 1003 or CSA B356 installed on the domestic water branch main or riser at the connection to the water service pipe where the main pressure exceeds it. IPC 607.3 - where a storage water heater is supplied with cold water that passes through a check valve, pressure-reducing valve, or backflow preventer, a thermal expansion control device connected to the cold water supply downstream of all such devices, and expansion tanks sized per the manufacturer so that system pressure does not exceed what 604.8 requires. Not checked: expansion tank size or precharge, per-fixture flow pressure and flow rate, pipe sizing and the friction, elevation, and meter losses between static and flowing pressure, seasonal pressure variation, PRV maintenance and failure modes, or the water heater's T and P relief and discharge piping. A screen; the adopted code, the device listings, and the AHJ govern."},
  "weir-flow": {"inputs":[{"key":"weir_type","label":"Weir type","kind":"select","options":[{"value":"vnotch90","label":"90-degree V-notch"},{"value":"rect_contracted","label":"Rectangular (contracted)"},{"value":"rect_suppressed","label":"Rectangular (suppressed)"}],"default":null,"attrs":null}],"citation":"Citation: Per the USBR Water Measurement Manual (public domain) - V-notch and Francis rectangular-weir equations and Kindsvater-Carter / Francis coefficients; the user confirms the calibrated weir coefficient. Requires a sharp-crested, ventilated, free-flow weir. Free at usbr.gov/tsc/techreferences/mands/wmm."},
  "weir-head-from-flow": {"inputs":[{"key":"weir_type","label":"Weir type","kind":"select","options":[{"value":"vnotch90","label":"90-degree V-notch"},{"value":"rect_contracted","label":"Rectangular (contracted)"},{"value":"rect_suppressed","label":"Rectangular (suppressed)"}],"default":null,"attrs":null}],"citation":"Citation: Per the USBR Water Measurement Manual (public domain) - the V-notch and Francis rectangular-weir equations solved for the head over the crest, the inverse of the weir-flow tile; the contracted weir is solved by fixed-point iteration. Requires a sharp-crested, ventilated, free-flow weir. Free at usbr.gov/tsc/techreferences/mands/wmm."},
  "weld-heat-input": {"inputs":[{"key":"process","label":"Process","kind":"select","options":[{"value":"SMAW","label":"SMAW"},{"value":"GMAW","label":"GMAW"},{"value":"FCAW","label":"FCAW"},{"value":"GTAW","label":"GTAW"},{"value":"SAW","label":"SAW"}],"default":null,"attrs":null}],"citation":"Citation: Per AWS D1.1 Structural Welding Code and ASME BPVC Section IX, the heat-input definition HI = (60 * V * I) / TS, by name, with an arc-efficiency factor by process. WPS/PQR ranges are user-supplied; the adopted code edition and the qualified WPS govern. Free overviews at aws.org."},
  "weld-metal-volume": {"inputs":[{"key":"joint_type","label":"Joint type","kind":"select","options":[{"value":"fillet","label":"Fillet (by leg)"},{"value":"groove","label":"Groove (by area)"}],"default":null,"attrs":null}],"citation":"Citation: first-principles joint geometry and steel density (0.2836 lb/in3), by name. Deposit volume = weld area x length; equal-leg fillet area = leg2 / 2; filler purchased = deposit / deposition efficiency. The WPS and the fabricator's measured deposition efficiency govern."},
  "wind-pressure": {"inputs":[{"key":"exposure","label":"Exposure","kind":"select","options":[{"value":"B","label":"B"},{"value":"C","label":"C"},{"value":"D","label":"D"}],"default":null,"attrs":null}],"citation":"Citation: q = 0.00256 * V^2 (V mph) per public ASCE 7 formula. Cp +0.8 windward, -0.5 leeward (typical)."},
  "wsfu-demand": {"inputs":[{"key":"system_type","label":"System type","kind":"select","options":[{"value":"flush_tank","label":"Flush tank (gravity)"},{"value":"flush_valve","label":"Flush valve (flushometer)"}],"default":null,"attrs":null}],"citation":"Citation: Hunter's curve (NBS BMS65, Methods of Estimating Loads in Plumbing Systems) and IPC 2021 Appendix E (Table E103.3(2)) by name; the demand curve ships as editable breakpoints, not a transcribed table."},
};
